#!/usr/bin/env bun
/**
 * fetch_events.ts — Fetch all GitHub events for an Issue or PR as a JSON
 * array (sorted by created_at), written to --out.
 *
 * Each event has: {id, event_type, content, author, created_at, sha?}
 *
 * Event types:
 *   issue_opened           — Issue body
 *   issue_comment          — Issue comment
 *   pr_opened               — PR body
 *   pr_diff                 — PR current diff (stable ID: "pr-{number}-diff")
 *   pr_comment               — PR conversation comment
 *   pr_review                — PR review submission (state + body)
 *   pr_review_comment        — PR inline review comment
 *
 * Usage:
 *   fetch_events.ts --type issue|pr --number N [--max-diff-chars N] --out events.json
 *
 * Requires GITHUB_REPOSITORY (owner/repo) in the environment.
 * Writes `resolved_type` / `resolved_number` to $GITHUB_OUTPUT. A PR linked
 * via `<!-- atoma:parent-issue=N -->` resolves to that canonical Issue so
 * Issue and PR runs share one serial conversation/session.
 */
import { appendFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { gh, ghJson, ghPaginated } from "../lib/gh.ts";
import { PARENT_ISSUE_TAG } from "../lib/tags.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface FetchEventsArgs {
  type: string;
  number: string | number;
  "max-diff-chars"?: string | number;
  out: string;
}

export const ref = defineScript<FetchEventsArgs>(import.meta.url);

export interface GithubEvent {
  id: string | number;
  event_type: string;
  content: string;
  author: string;
  created_at: string;
  sha?: string;
}

interface GhIssueApi {
  number: number;
  title: string;
  body: string | null;
  labels: { name: string }[];
  user: { login: string };
  created_at: string;
}

interface GhCommentApi {
  id: number;
  body: string;
  user: { login: string };
  created_at: string;
}

interface GhPrApi {
  number: number;
  title: string;
  body: string | null;
  user: { login: string };
  created_at: string;
  updated_at: string;
  labels: { name: string }[];
  head: { sha: string };
}

interface GhReviewApi {
  id: number;
  body: string | null;
  state: string;
  user: { login: string };
  submitted_at: string | null;
}

interface GhReviewCommentApi {
  id: number;
  path: string;
  line: number | null;
  original_line: number | null;
  body: string;
  user: { login: string };
  created_at: string;
}

export interface FetchEventsResult {
  events: GithubEvent[];
  resolvedType: "issue" | "pr";
  resolvedNumber: number;
}

function repoParts(): [string, string] {
  const repo = process.env.GITHUB_REPOSITORY ?? "";
  const [owner, name] = repo.split("/", 2);
  if (!owner || !name) throw new Error(`GITHUB_REPOSITORY is not set or malformed: "${repo}"`);
  return [owner, name];
}

function fetchIssueEvents(
  owner: string,
  repo: string,
  issueNum: number,
  openedType: string,
  commentType: string,
  idPrefix: string,
): GithubEvent[] {
  const issue = JSON.parse(gh("api", `repos/${owner}/${repo}/issues/${issueNum}`).stdout) as GhIssueApi;

  const labelsLine = issue.labels.length > 0 ? `**Labels:** ${issue.labels.map((l) => l.name).join(", ")}\n` : "";
  const openedEvent: GithubEvent = {
    id: `${idPrefix}-${issue.number}`,
    event_type: openedType,
    content: `Issue #${issue.number}: ${issue.title}\n${labelsLine}\n${issue.body ?? ""}`,
    author: issue.user.login,
    created_at: issue.created_at,
  };

  const comments = ghPaginated<GhCommentApi>("api", `repos/${owner}/${repo}/issues/${issueNum}/comments`);
  const commentEvents: GithubEvent[] = comments.map((c) => ({
    id: c.id,
    event_type: commentType,
    content: c.body,
    author: c.user.login,
    created_at: c.created_at,
  }));

  return [openedEvent, ...commentEvents];
}

function fetchPrEvents(owner: string, repo: string, number: number, maxDiffChars: number): { events: GithubEvent[]; parentIssue?: number } {
  const pr = JSON.parse(gh("api", `repos/${owner}/${repo}/pulls/${number}`).stdout) as GhPrApi;
  const prBody = pr.body ?? "";
  const parentIssue = PARENT_ISSUE_TAG.read(prBody);
  const headSha = pr.head.sha.slice(0, 8);
  const events: GithubEvent[] = [];

  const labelsLine = pr.labels.length > 0 ? `**Labels:** ${pr.labels.map((label) => label.name).join(", ")}` : "";
  const linkedLine = parentIssue ? `**Linked Issue:** #${parentIssue}` : "";
  const prContentLines = [`PR #${number}: ${pr.title}`, labelsLine, linkedLine].filter(Boolean);
  prContentLines.push("", prBody);
  events.push({
    id: `pr-${number}`,
    event_type: "pr_opened",
    content: prContentLines.join("\n"),
    author: pr.user.login,
    created_at: pr.created_at,
  });

  const diffResult = gh("api", `repos/${owner}/${repo}/pulls/${number}`, "-H", "Accept: application/vnd.github.v3.diff");
  const diff = diffResult.code === 0 ? diffResult.stdout : "";
  if (diff) {
    const truncated = diff.slice(0, maxDiffChars);
    let diffContent = "```diff\n" + truncated + "\n```";
    if (diff.length > maxDiffChars) diffContent += `\n\n*[Diff truncated at ${maxDiffChars} characters due to size]*`;
    events.push({
      id: `pr-${number}-diff`,
      event_type: "pr_diff",
      content: diffContent,
      sha: headSha,
      author: "github",
      created_at: pr.updated_at,
    });
  }

  const prComments = ghPaginated<GhCommentApi>("api", `repos/${owner}/${repo}/issues/${number}/comments`);
  events.push(...prComments.map((comment) => ({
    id: comment.id,
    event_type: "pr_comment",
    content: comment.body,
    author: comment.user.login,
    created_at: comment.created_at,
  })));

  const reviews = ghPaginated<GhReviewApi>("api", `repos/${owner}/${repo}/pulls/${number}/reviews`);
  events.push(...reviews.filter((review) => review.submitted_at != null).map((review) => ({
    id: `pr-review-${review.id}`,
    event_type: "pr_review",
    content: `Review state: ${review.state}\n\n${review.body ?? ""}`,
    author: review.user.login,
    created_at: review.submitted_at!,
  })));

  const inlineComments = ghPaginated<GhReviewCommentApi>("api", `repos/${owner}/${repo}/pulls/${number}/comments`);
  events.push(...inlineComments.map((comment) => ({
    id: comment.id,
    event_type: "pr_review_comment",
    content: `On \`${comment.path}\` line ${comment.line ?? comment.original_line ?? "?"}:\n\n${comment.body}`,
    author: comment.user.login,
    created_at: comment.created_at,
  })));

  return { events, parentIssue };
}

function linkedPrNumbers(owner: string, repo: string, issueNumber: number): number[] {
  const prs = ghJson<{ number: number }[]>(
    "pr", "list", "--repo", `${owner}/${repo}`, "--state", "all",
    "--search", `atoma:parent-issue=${issueNumber} in:body`,
    "--limit", "1000", "--json", "number",
  ) ?? [];
  if (prs.length === 1000) {
    console.error(`::warning::Linked PR search for Issue #${issueNumber} reached GitHub's 1000-result search limit.`);
  }
  return prs.map((pr) => pr.number);
}

function tryLinkedPrNumbers(owner: string, repo: string, issueNumber: number): number[] {
  try {
    return linkedPrNumbers(owner, repo, issueNumber);
  } catch {
    console.error(`::warning::Could not search linked PRs for Issue #${issueNumber}; using the available context.`);
    return [];
  }
}

function appendPrEvents(
  events: GithubEvent[],
  owner: string,
  repo: string,
  prNumber: number,
  maxDiffChars: number,
): void {
  try {
    events.push(...fetchPrEvents(owner, repo, prNumber, maxDiffChars).events);
  } catch {
    console.error(`::warning::Could not fetch linked PR #${prNumber}; skipping it.`);
  }
}

export function fetchEvents(
  type: "issue" | "pr",
  number: number,
  maxDiffChars: number,
): FetchEventsResult {
  const [owner, repo] = repoParts();

  if (type === "issue") {
    const events = fetchIssueEvents(owner, repo, number, "issue_opened", "issue_comment", "issue");
    for (const prNumber of tryLinkedPrNumbers(owner, repo, number)) {
      appendPrEvents(events, owner, repo, prNumber, maxDiffChars);
    }
    events.sort((a, b) => a.created_at.localeCompare(b.created_at));
    return { events, resolvedType: "issue", resolvedNumber: number };
  }

  const prResult = fetchPrEvents(owner, repo, number, maxDiffChars);
  let events = [...prResult.events];
  if (prResult.parentIssue) {
    try {
      events = fetchIssueEvents(owner, repo, prResult.parentIssue, "issue_opened", "issue_comment", "issue");
      const relatedPrNumbers = new Set([number, ...tryLinkedPrNumbers(owner, repo, prResult.parentIssue)]);
      for (const relatedPrNumber of relatedPrNumbers) {
        if (relatedPrNumber === number) events.push(...prResult.events);
        else appendPrEvents(events, owner, repo, relatedPrNumber, maxDiffChars);
      }
    } catch {
      console.error(`::warning::Linked Issue #${prResult.parentIssue} not found or inaccessible — using PR-local context.`);
      events.sort((a, b) => a.created_at.localeCompare(b.created_at));
      return { events, resolvedType: "pr", resolvedNumber: number };
    }
  }

  events.sort((a, b) => a.created_at.localeCompare(b.created_at));
  return {
    events,
    resolvedType: prResult.parentIssue ? "issue" : "pr",
    resolvedNumber: prResult.parentIssue ?? number,
  };
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      type: { type: "string" },
      number: { type: "string" },
      "max-diff-chars": { type: "string" },
      out: { type: "string" },
    },
  });

  if ((values.type !== "issue" && values.type !== "pr") || !values.number || !values.out) {
    console.error("usage: fetch_events.ts --type issue|pr --number N [--max-diff-chars N] --out events.json");
    process.exit(2);
  }

  const maxDiffChars = Number(values["max-diff-chars"] ?? 30000);
  const { events, resolvedType, resolvedNumber } = fetchEvents(values.type, Number(values.number), maxDiffChars);

  writeFileSync(values.out, JSON.stringify(events, null, 2));

  const githubOutput = process.env.GITHUB_OUTPUT;
  if (githubOutput) appendFileSync(githubOutput, `resolved_type=${resolvedType}\nresolved_number=${resolvedNumber}\n`);

  console.error(`Fetched ${events.length} events → ${values.out}`);
}

if (import.meta.main) main();

#!/usr/bin/env bun
/**
 * restore_agent_session.ts — Restore a per-agent session.json from the
 * `atoma-data` branch (if one exists yet for this type/number/agent),
 * without disturbing the current checkout.
 *
 * Usage: restore_agent_session.ts --type issue|pr --number N --agent NAME --out session.json
 * No-ops quietly (does not create --out) if no prior session is found.
 */
import { writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { archiveSession, restoreSession, sessionTargetPath } from "./lib/atoma-data.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface RestoreAgentSessionArgs {
  type: string;
  number: string | number;
  agent: string;
  out: string;
  "session-mode"?: string;
}

export const ref = defineScript<RestoreAgentSessionArgs>(import.meta.url);

export interface RestoredAgentSession {
  target: string;
  content?: string;
}

export function findAgentSession(
  type: string,
  number: string | number,
  agent: string,
  load: (target: string) => string | undefined = restoreSession,
): RestoredAgentSession {
  const target = sessionTargetPath(type, number, agent);
  return { target, content: load(target) };
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      type: { type: "string" },
      number: { type: "string" },
      agent: { type: "string" },
      out: { type: "string" },
      "session-mode": { type: "string" },
    },
  });
  if (!values.type || !values.number || !values.agent || !values.out) {
    console.error("usage: restore_agent_session.ts --type issue|pr --number N --agent NAME --out session.json");
    process.exit(2);
  }

  const { target, content } = findAgentSession(
    values.type,
    values.number,
    values.agent,
  );
  if (values["session-mode"] === "recover") {
    if (content === undefined) {
      console.error(`No existing session at ${target}; recovery will start fresh without an archive.`);
      return;
    }
    const archivedPath = archiveSession(values.type, values.number, values.agent, content);
    if (!archivedPath) throw new Error(`Failed to archive existing session before recovery: ${target}`);
    console.error(`Archived session to atoma-data:${archivedPath}; starting fresh.`);
    return;
  }
  if (content !== undefined) {
    writeFileSync(values.out, content);
    console.error(`Restored session: ${target}`);
  } else {
    console.error(`No existing session at ${target}, starting fresh.`);
  }
}

if (import.meta.main) main();

#!/usr/bin/env bun
/**
 * run_environment_setup.ts — Run each command in config.json's
 * `environment.setup_commands` (if any) via `bash -c`, before the agent
 * starts, so it never has to spend iterations/tool calls doing one-off
 * environment prep itself on a cold runner. No-ops quietly if unset/empty.
 *
 * Mirrors GitHub Actions' own default `bash -e {0}` semantics: the first
 * failing command aborts immediately with its exit code.
 */
import { loadConfig } from "../lib/config.ts";
import { defineScript } from "./lib/script-ref.ts";

export const ref = defineScript(import.meta.url);

function main(): void {
  const commands = loadConfig().environment?.setup_commands ?? [];
  if (commands.length === 0) {
    console.log("No environment.setup_commands configured; skipping.");
    return;
  }
  for (const cmd of commands) {
    console.log(`Running environment setup command: ${cmd}`);
    const result = Bun.spawnSync({ cmd: ["bash", "-c", cmd], stdout: "inherit", stderr: "inherit" });
    if (result.exitCode !== 0) {
      console.error(`environment setup command failed (exit ${result.exitCode}): ${cmd}`);
      process.exit(result.exitCode ?? 1);
    }
  }
}

if (import.meta.main) main();

#!/usr/bin/env bun
/**
 * Print a dotted-path value from .github/atoma/config.json.
 *
 * Thin CLI wrapper around lib/config.ts's loadConfig(), invoked as a
 * workflow step (via `scriptCommand` from atoma-runner.wac.ts). Every
 * other callers import loadConfig() directly.
 *
 * Usage:
 *   bun run get_config_value.ts <dotted.path> [default]
 *
 * Examples:
 *   bun run get_config_value.ts agents.engineer.max_iterations 30
 *   bun run get_config_value.ts labels.in_progress atoma/in-progress
 */
import { loadConfig } from "../lib/config.ts";
import { defineScript } from "./lib/script-ref.ts";

export const ref = defineScript(import.meta.url);

/** Build the positional argv for this script, used by callers for a type-checked invocation. */
export function buildArgv(path: string, fallback?: string): string[] {
  return fallback === undefined ? [`"${path}"`] : [`"${path}"`, `"${fallback}"`];
}

function main(): void {
  const [path, fallback = ""] = Bun.argv.slice(2);
  if (!path) {
    console.error("usage: get_config_value.ts <dotted.path> [default]");
    process.exit(2);
  }

  let node: unknown = loadConfig();
  for (const key of path.split(".")) {
    if (node && typeof node === "object" && key in node) {
      node = (node as Record<string, unknown>)[key];
    } else {
      console.log(fallback);
      return;
    }
  }
  console.log(node);
}

if (import.meta.main) main();

#!/usr/bin/env bun
/**
 * reconcile_github_session.ts — Reconcile GitHub events into the durable
 * per-agent session.
 *
 * GitHub messages are persisted in session.json so the original task remains
 * a stable early prompt prefix. Existing events update in place and genuinely
 * new events append after prior agent history, preserving cross-run chronology
 * and provider prompt-cache reuse.
 *
 * Algorithm:
 *   1. Load the cached per-agent session (optional) to inspect:
 *        - assistant github_comment_id values posted by this agent
 *        - the previously processed shared-context snapshot hash
 *   2. Filter fetched GitHub events:
 *        - keep issue/PR bodies, diffs, human comments, and other-agent comments
 *        - exclude this agent's own result comments
 *        - apply the agent's configured shared_context include/exclude policy, if any
 *   3. Reconcile the filtered events into session.json by stable event ID.
 *   4. Compute a snapshot hash for change detection.
 *   5. Write new_event_count/context_snapshot_hash/context_event_count to $GITHUB_OUTPUT.
 *
 * Usage:
 *   reconcile_github_session.ts --events events.json --agent-name orchestrator \
 *     --session session.json [--config config.json] --out session.json
 */
import { createHash } from "node:crypto";
import { appendFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { defineScript } from "./lib/script-ref.ts";
import type { GithubEvent } from "./fetch_events.ts";
import type { Session, SessionMessage, SessionMessageMetadata } from "../lib/session.ts";
import { AGENT_TAG, LLM_CONTEXT_TAG } from "../lib/tags.ts";

export interface ReconcileGithubSessionArgs {
  events: string;
  "agent-name": string;
  config?: string;
  session?: string;
  out: string;
}

export const ref = defineScript<ReconcileGithubSessionArgs>(import.meta.url);

const GITHUB_CONTEXT_LAYER = "github-context";

interface SharedContextConfig {
  agents?: Record<string, { shared_context?: { include_event_types?: string[]; exclude_event_types?: string[] } }>;
}

interface GithubEventMessage extends SessionMessage {
  role: "user";
  content: string;
  atoma_metadata: SessionMessageMetadata & {
    source: "github";
    layer: string;
    event_type: string;
    id: string | number;
    author: string;
    created_at: string;
    sha?: string;
  };
}

export interface ReconcileGithubSessionResult {
  mergedSession: Session;
  changedCount: number;
  snapshotHash: string;
  eventCount: number;
}

function githubEventKey(message: SessionMessage): string | undefined {
  const metadata = message.atoma_metadata;
  if (metadata?.source !== "github" || metadata.layer !== GITHUB_CONTEXT_LAYER) return undefined;
  if (metadata.event_type === undefined || metadata.id === undefined) return undefined;
  return `${String(metadata.event_type)}:${String(metadata.id)}`;
}

function githubEventKeyFromEvent(event: GithubEvent): string {
  return `${event.event_type}:${String(event.id)}`;
}

function deletedGithubMessage(message: SessionMessage): SessionMessage {
  if (message.atoma_metadata?.deleted === true) return message;
  return {
    role: "user",
    content: `[Deleted GitHub ${String(message.atoma_metadata?.event_type ?? "event")}]`,
    atoma_metadata: { ...message.atoma_metadata, deleted: true },
  };
}

function reconcilePersistedGithubContext(
  session: Session,
  messages: GithubEventMessage[],
  fetchedEventKeys: ReadonlySet<string>,
): Session {
  const incomingByKey = new Map(messages.map((message) => [githubEventKey(message)!, message]));
  const seen = new Set<string>();
  const reconciled: SessionMessage[] = [];

  for (const message of session.messages ?? []) {
    const key = githubEventKey(message);
    if (key === undefined) {
      reconciled.push(message);
      continue;
    }

    const replacement = incomingByKey.get(key);
    if (replacement !== undefined && !seen.has(key)) {
      reconciled.push(replacement);
      seen.add(key);
    } else if (!fetchedEventKeys.has(key) && !seen.has(key)) {
      reconciled.push(deletedGithubMessage(message));
      seen.add(key);
    }
  }

  for (const message of messages) {
    const key = githubEventKey(message)!;
    if (!seen.has(key)) {
      reconciled.push(message);
      seen.add(key);
    }
  }

  return { ...session, messages: reconciled };
}

/**
 * Reconcile the current GitHub snapshot into the durable agent session.
 * Existing events keep their position, changed events update in place, and
 * genuinely new events append after the agent history that preceded them.
 */
export function mergeGithubContext(
  session: Session,
  messages: GithubEventMessage[],
  fetchedEventKeys: ReadonlySet<string> = new Set(messages.map((message) => githubEventKey(message)!)),
): Session {
  const existingMessages = session.messages ?? [];
  if (session.metadata?.github_context?.version === 1) {
    return reconcilePersistedGithubContext(session, messages, fetchedEventKeys);
  }

  const firstHistoryIndex = existingMessages.findIndex((message) => message.role !== "system");
  const insertionIndex = firstHistoryIndex === -1 ? existingMessages.length : firstHistoryIndex;
  return {
    ...session,
    messages: [
      ...existingMessages.slice(0, insertionIndex),
      ...messages,
      ...existingMessages.slice(insertionIndex),
    ],
  };
}

function normalizeId(val: string | number | undefined): string | undefined {
  return val === undefined ? undefined : String(val);
}

function buildOwnCommentIds(session: Session, agentName: string): Set<string> {
  const ownIds = new Set<string>();
  for (const msg of session.messages ?? []) {
    const meta = msg.atoma_metadata;
    if (msg.role !== "assistant" || !meta || meta.github_comment_id === undefined) continue;
    if (meta.agent !== undefined && meta.agent !== agentName) continue;
    const id = normalizeId(meta.github_comment_id);
    if (id !== undefined) ownIds.add(id);
  }
  return ownIds;
}

function extractResultCommentAgent(event: GithubEvent): string | undefined {
  if (!event.author.endsWith("[bot]")) return undefined;
  if (!event.content) return undefined;
  const firstLine = event.content.split("\n")[0]!.trim();
  return AGENT_TAG.read(firstLine);
}

function isSelfEvent(event: GithubEvent, agentName: string, ownCommentIds: Set<string>): boolean {
  const eventId = normalizeId(event.id);
  if (eventId !== undefined && ownCommentIds.has(eventId)) return true;
  return extractResultCommentAgent(event) === agentName;
}

function contextPolicy(config: SharedContextConfig, agentName: string): { include?: Set<string>; exclude: Set<string> } {
  const sharedContext = config.agents?.[agentName]?.shared_context;
  if (!sharedContext) return { exclude: new Set() };
  return {
    include: sharedContext.include_event_types ? new Set(sharedContext.include_event_types) : undefined,
    exclude: new Set(sharedContext.exclude_event_types ?? []),
  };
}

function filterEventsForAgent(
  events: GithubEvent[],
  agentName: string,
  ownCommentIds: Set<string>,
  config: SharedContextConfig,
): GithubEvent[] {
  const { include, exclude } = contextPolicy(config, agentName);
  const filtered: GithubEvent[] = [];
  for (const event of events) {
    if (event.author.endsWith("[bot]") && LLM_CONTEXT_TAG.read(event.content) === "exclude") {
      console.error(`  Skipping operational notification from LLM context: id=${event.id}`);
      continue;
    }
    if (isSelfEvent(event, agentName, ownCommentIds)) {
      console.error(`  Skipping current agent comment from shared context: id=${event.id}`);
      continue;
    }
    if (include && !include.has(event.event_type)) continue;
    if (exclude.has(event.event_type)) continue;
    filtered.push(event);
  }
  return filtered;
}

function eventToUserMessage(event: GithubEvent): GithubEventMessage {
  return {
    role: "user",
    content: event.content,
    atoma_metadata: {
      source: "github",
      layer: GITHUB_CONTEXT_LAYER,
      event_type: event.event_type,
      id: event.id,
      author: event.author ?? "unknown",
      created_at: event.created_at ?? "",
      ...(event.sha !== undefined ? { sha: event.sha } : {}),
    },
  };
}

/** Deterministic JSON serialization (recursively sorted object keys, no whitespace) for stable hashing. */
function canonicalStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalStringify).join(",")}]`;
  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalStringify(obj[k])}`).join(",")}}`;
}

function snapshotHashForEvents(events: GithubEvent[]): string {
  return createHash("sha256").update(canonicalStringify(events)).digest("hex");
}

function previousSnapshotHash(session: Session): string | undefined {
  return session.metadata?.github_context?.snapshot_hash;
}

export function reconcileGithubSession(
  session: Session,
  events: GithubEvent[],
  agentName: string,
  config: SharedContextConfig = {},
): ReconcileGithubSessionResult {
  const ownCommentIds = buildOwnCommentIds(session, agentName);
  const filteredEvents = filterEventsForAgent(events, agentName, ownCommentIds, config);
  const currentHash = snapshotHashForEvents(filteredEvents);
  const previousHash = previousSnapshotHash(session);
  const contextMessages = filteredEvents.map(eventToUserMessage);
  const fetchedEventKeys = new Set(events.map(githubEventKeyFromEvent));

  let changedCount: number;
  if (previousHash === currentHash) changedCount = 0;
  else if (previousHash === undefined) changedCount = filteredEvents.length;
  else changedCount = 1;

  const mergedSession = mergeGithubContext(session, contextMessages, fetchedEventKeys);
  mergedSession.metadata = {
    ...mergedSession.metadata,
    github_context: {
      ...mergedSession.metadata?.github_context,
      version: 1,
      snapshot_hash: currentHash,
      event_count: filteredEvents.length,
      agent: agentName,
    },
  };

  return {
    mergedSession,
    changedCount,
    snapshotHash: currentHash,
    eventCount: filteredEvents.length,
  };
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      events: { type: "string" },
      "agent-name": { type: "string" },
      config: { type: "string" },
      session: { type: "string" },
      out: { type: "string" },
    },
  });

  if (!values.events || !values["agent-name"] || !values.session || !values.out) {
    console.error(
      "usage: reconcile_github_session.ts --events events.json --agent-name AGENT --session session.json [--config config.json] --out session.json",
    );
    process.exit(2);
  }

  const session: Session = existsSync(values.session) ? JSON.parse(readFileSync(values.session, "utf8")) : { messages: [] };
  const events = JSON.parse(readFileSync(values.events, "utf8")) as GithubEvent[];
  const config: SharedContextConfig = values.config && existsSync(values.config) ? JSON.parse(readFileSync(values.config, "utf8")) : {};

  const { mergedSession, changedCount, snapshotHash, eventCount } = reconcileGithubSession(session, events, values["agent-name"], config);

  writeFileSync(values.out, JSON.stringify(mergedSession, null, 2) + "\n");

  const githubOutput = process.env.GITHUB_OUTPUT;
  if (githubOutput) {
    appendFileSync(
      githubOutput,
      `new_event_count=${changedCount}\ncontext_snapshot_hash=${snapshotHash}\ncontext_event_count=${eventCount}\n`,
    );
  }

  console.error(
    `Context build complete: ${events.length} events fetched, ${eventCount} shared messages, changed=${changedCount}`,
  );
}

if (import.meta.main) main();

#!/usr/bin/env bun
/**
 * github.ts — Unified GitHub MCP server for Atoma.
 *
 * Transport: stdio, via the official @modelcontextprotocol/sdk.
 * Dependencies: `gh` CLI + `git`.
 *
 * Every mutation is logged to $ATOMA_OPS_LOG (see lib/ops-log.ts) as a
 * general audit trail; dispatch decisions specifically are also what
 * atoma-runner.wac.ts's chain_continues detection reads.
 *
 * IMPORTANT: this process's `process.stdout` IS the JSON-RPC transport --
 * never `console.log()` anywhere in this file or in anything it calls
 * in-process (resolveNotify/dispatchOrchestratorIfSubIssueReady/etc.);
 * always `console.error()` (`log()` below) for logging.
 */
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { gh, ghGraphql, gitRun } from "../../../../lib/gh.ts";
import { getLabel, getMergePolicy, getTriggerAgent } from "../../../../lib/config.ts";
import { resolveNotify } from "../../../../lib/notify.ts";
import { dispatchOrchestratorIfSubIssueReady } from "../../../../lib/aggregation.ts";
import { logDispatch, logOp } from "../../../../lib/ops-log.ts";
import { LLM_CONTEXT_TAG, NOTIFY_TAG, ORIGIN_AGENT_TAG, PARENT_ISSUE_TAG, PARENT_TAG } from "../../../../lib/tags.ts";
import type { GhIssueAuthor } from "../../../../lib/types.ts";
import { buildMcpTools, defineMcpTool, z, type McpToolResult } from "../../../../lib/mcp-tool.ts";
import { decidePostMergeHandoff } from "../../../../domain/handoff.ts";

function log(msg: string): void {
  console.error(`[atoma-github] ${msg}`);
}

let REPO = process.env.GITHUB_REPOSITORY ?? "";
// Fallback: derive REPO from git remote if env var is not set.
if (!REPO) {
  try {
    const { code, stdout } = gitRun("remote", "get-url", "origin");
    if (code === 0 && stdout) {
      const url = stdout.trim();
      for (const prefix of ["https://github.com/", "git@github.com:"]) {
        if (url.startsWith(prefix)) {
          const suffix = url.slice(prefix.length);
          REPO = suffix.endsWith(".git") ? suffix.slice(0, -4) : suffix;
          break;
        }
      }
    }
  } catch {
    // best-effort
  }
}

function mcpFail(message: string): never {
  throw new Error(message);
}

function ghJsonOrThrow<T>(...args: string[]): T {
  const { code, stdout, stderr } = gh(...args);
  if (code) mcpFail(stderr || stdout);
  return stdout ? (JSON.parse(stdout) as T) : (null as T);
}

async function resolveIssueId(number: number): Promise<string> {
  const [owner, repo] = REPO.split("/", 2);
  const d = ghGraphql<{ repository: { issue: { id: string } } }>(
    "query($owner:String!,$repo:String!,$num:Int!){repository(owner:$owner,name:$repo){issue(number:$num){id}}}",
    { owner: owner!, repo: repo!, num: number },
  );
  return d.repository.issue.id;
}

/** Shared schema for tools that take a single required `number` (issue/PR number) argument. */
const NUMBER_ARG_SCHEMA = z.object({
  number: z.number().int().positive().describe("Positive GitHub issue or pull request number, without a leading '#'."),
});

const CREATE_ISSUE_SCHEMA = z.object({
  title: z.string().min(1).describe("Concise issue title."),
  body: z.string().optional().describe("Issue body in GitHub-flavored Markdown. Defaults to an empty body."),
  labels: z.array(z.string()).optional().describe("Existing repository label names to apply. Defaults to no extra labels."),
  sub_issue: z
    .boolean()
    .optional()
    .describe("Set sub_issue=true to automatically link it to the current issue as a child task. Defaults to true."),
});

const LIST_ISSUES_SCHEMA = z.object({
  state: z.enum(["open", "closed", "all"]).optional().describe("Issue state filter. Defaults to 'open'."),
  labels: z.array(z.string()).optional().describe("Return only issues matching these repository labels."),
  limit: z.number().int().positive().max(100).optional().describe("Maximum issues to return. Defaults to 30; maximum 100."),
});

const CREATE_PR_SCHEMA = z.object({
  title: z.string().min(1).describe("Concise pull request title."),
  body: z.string().optional().describe("Pull request body in GitHub-flavored Markdown. Atoma adds issue traceability metadata automatically."),
  base: z.string().optional().describe("Target branch name. Omit to use the repository default branch."),
});

const LIST_PRS_SCHEMA = z.object({
  state: z.enum(["open", "closed", "merged", "all"]).optional().describe("Pull request state filter. Defaults to 'open'."),
  limit: z.number().int().positive().max(100).optional().describe("Maximum pull requests to return. Defaults to 30; maximum 100."),
});

const SEARCH_CODE_SCHEMA = z.object({
  query: z.string().min(1).describe("GitHub code-search query scoped automatically to the current repository."),
});
const GET_BRANCH_SCHEMA = z.object({
  name: z.string().min(1).describe("Repository branch name, for example 'main' or 'atoma/issue-42'."),
});
const GET_CHECK_RUNS_SCHEMA = z.object({
  ref: z.string().min(1).describe("Commit SHA, branch name, or tag whose GitHub check runs should be returned."),
});
const SYNC_BRANCH_SCHEMA = z.object({
  branch: z.string().optional().describe("Branch to synchronize. Defaults to the current Atoma branch."),
});

const SUBMIT_PR_REVIEW_SCHEMA = z.object({
  number: z.number().int().positive().describe("Positive pull request number, without a leading '#'."),
  event: z.enum(["COMMENT", "REQUEST_CHANGES"]).describe("Review outcome. Use COMMENT for approval-like feedback because GitHub forbids bot self-approval."),
  body: z.string().optional().describe("Review summary in GitHub-flavored Markdown. Required in practice for REQUEST_CHANGES."),
});

const COMMIT_AND_PUSH_SCHEMA = z.object({
  message: z.string().describe("Commit message."),
});


function notifyTagPrefix(): string {
  const login = (process.env.ISSUE_NOTIFY ?? "").trim();
  return login ? `${NOTIFY_TAG.write(login)}\n` : "";
}

async function createIssue(a: z.infer<typeof CREATE_ISSUE_SCHEMA>): Promise<string> {
  const title = a.title;
  let body = a.body ?? "";
  let labels = a.labels ?? [];
  const sub = a.sub_issue ?? true;
  const parentNum = (process.env.ISSUE_NUMBER ?? "").trim();

  body = notifyTagPrefix() + body;
  if (sub) {
    if (parentNum) body = `${PARENT_TAG.write(Number(parentNum))}\n${body}`;
    const subIssueLabel = getLabel("sub_issue", "atoma/sub-issue");
    const ensured = gh(
      "label", "create", subIssueLabel,
      "--repo", REPO,
      "--force",
      "--color", "8250df",
      "--description", "Child delivery task managed by Atoma",
    );
    if (ensured.code) mcpFail(`Failed to ensure sub-issue label '${subIssueLabel}': ${ensured.stderr || ensured.stdout}`);
    if (!labels.includes(subIssueLabel)) labels = [...labels, subIssueLabel];
  }

  const cmd = ["issue", "create", "--repo", REPO, "--title", title];
  if (body) cmd.push("--body", body);
  for (const l of labels) cmd.push("--label", l);

  const { code, stdout, stderr } = gh(...cmd);
  if (code) mcpFail(stderr || stdout);
  const num = Number(stdout.trim().split("/").pop());
  if (!Number.isFinite(num)) mcpFail(`gh issue create: unexpected output: ${stdout.slice(0, 300)}`);

  if (sub && parentNum) {
    try {
      const pid = await resolveIssueId(Number(parentNum));
      const sid = await resolveIssueId(num);
      ghGraphql(
        "mutation($parent:ID!,$sub:ID!){addSubIssue(input:{issueId:$parent,subIssueId:$sub,replaceParent:true}){issue{number}}}",
        { parent: pid, sub: sid },
      );
      log(`Linked sub-issue #${num} to parent #${parentNum} via official sub-issues API`);
    } catch (e) {
      log(`WARN: Failed to link sub-issue #${num} to parent #${parentNum}: ${e}`);
    }
  }

  logOp("create_issue", { number: num, title, sub_issue: sub });
  return JSON.stringify({ number: num, url: stdout.trim() });
}

function getIssue(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  return JSON.stringify(ghJsonOrThrow("issue", "view", String(a.number), "--repo", REPO, "--json", "number,title,body,state,labels,createdAt,closedAt,comments"));
}

function listIssues(a: z.infer<typeof LIST_ISSUES_SCHEMA>): string {
  const state = a.state ?? "open";
  const limit = a.limit ?? 30;
  const labels = a.labels ?? [];
  const cmd = ["issue", "list", "--repo", REPO, "--state", state, "--limit", String(limit), "--json", "number,title,state,labels"];
  for (const l of labels) cmd.push("--label", l);
  return JSON.stringify(ghJsonOrThrow(...cmd) ?? []);
}

function getIssueComments(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  const d = ghJsonOrThrow<{ comments?: unknown[] }>("issue", "view", String(a.number), "--repo", REPO, "--json", "comments");
  return JSON.stringify(d?.comments ?? []);
}

function closeIssue(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  const num = a.number;
  log(`closeIssue: #${num}`);
  // Refuse to close issues opened by humans.
  // NOTE: `gh issue view --json author` returns {id, is_bot, login, name} --
  // there is NO `.type` field (that only exists on the REST
  // `gh api repos/OWNER/REPO/issues/N` endpoint, as `.user.type`). Use the
  // reliable `.author.is_bot` boolean instead.
  const d = ghJsonOrThrow<GhIssueAuthor>("issue", "view", String(num), "--repo", REPO, "--json", "author");
  const isBot = Boolean(d?.author?.is_bot);
  log(`closeIssue: author.is_bot=${isBot}`);
  if (!isBot) mcpFail(`Refusing to close issue #${num}: opened by a human, not a bot`);
  const { code, stdout, stderr } = gh("issue", "close", String(num), "--repo", REPO);
  if (code) mcpFail(stderr || stdout);
  logOp("close_issue", { number: num });
  return JSON.stringify({ ok: true });
}

/**
 * Runs closeIssue()'s own logic, then -- whether this is a sub-issue closed
 * via the normal merge_pr path or via an origin-agent re-invocation
 * confirming its own work -- checks phase-gating/aggregation for its
 * parent, so it fires regardless of which path closed the issue.
 * dispatchOrchestratorIfSubIssueReady no-ops harmlessly if #num has no
 * atoma:parent tag. Awaited by every caller (matching the original
 * Bun.spawnSync-based blocking behavior) so the tool response isn't
 * returned before phase-gating has actually run.
 */
async function closeIssueAndDispatch(a: z.infer<typeof NUMBER_ARG_SCHEMA>): Promise<string> {
  const result = closeIssue(a);
  const num = a.number;
  try {
    await dispatchOrchestratorIfSubIssueReady(REPO, num);
  } catch (e) {
    log(`closeIssueAndDispatch: dispatchOrchestratorIfSubIssueReady failed for #${num}: ${e}`);
  }
  return result;
}

function resolveBranch(): string {
  const br = (process.env.BRANCH ?? "").trim();
  if (br && br !== "HEAD") return br;
  {
    const { code, stdout } = gitRun("rev-parse", "--abbrev-ref", "HEAD");
    if (code === 0 && stdout && stdout !== "HEAD") return stdout;
  }
  {
    const { code, stdout } = gitRun("branch", "--format=%(refname:short)", "--points-at=HEAD");
    if (code === 0 && stdout) return stdout.split("\n")[0]!;
  }
  mcpFail("Cannot determine branch name; set BRANCH env");
}

function injectParentIssue(body: string): string {
  const parent = (process.env.ISSUE_NUMBER ?? "").trim();
  if (NOTIFY_TAG.has(body)) mcpFail("PR body already contains a notify tag; refusing to add another");
  body = notifyTagPrefix() + body;
  if (!parent) return body;
  if (PARENT_ISSUE_TAG.has(body)) {
    mcpFail("PR body already contains a parent-issue tag; refusing to add another");
  }
  // Inject parent-issue metadata always, but only add "Closes #N" if the body
  // doesn't already reference it -- agents sometimes write their own closing
  // keyword, and a duplicate "Closes #N" line makes downstream parsing match
  // twice, corrupting $GITHUB_OUTPUT.
  let closesLine = "";
  if (!new RegExp(`\\bcloses\\s+#${parent}\\b`, "i").test(body)) {
    closesLine = `Closes #${parent}\n`;
  }
  const originAgent = (process.env.AGENT ?? "").trim();
  const originLine = originAgent ? `${ORIGIN_AGENT_TAG.write(originAgent)}\n` : "";
  return `${PARENT_ISSUE_TAG.write(Number(parent))}\n${originLine}${closesLine}${body}`;
}

/**
 * Directly dispatch whichever agent config.json's auto_triggers designates
 * for a newly opened PR ("pull_request.opened", normally "reviewer" -- but
 * read from config, never hardcoded). GitHub suppresses further
 * workflow-triggering events for actions performed with the default
 * GITHUB_TOKEN, so a bot-created PR does NOT reliably cause
 * atoma-auto-trigger.yml to fire. workflow_dispatch is exempt from that
 * restriction, so dispatch directly here, the same way dispatchSubAgent
 * handles orchestrator -> sub-agent handoffs. Best-effort: a dispatch
 * failure does not fail PR creation itself.
 */
function dispatchPostPrAgent(prNumber: number): void {
  const agent = getTriggerAgent("pull_request.opened", "reviewer");
  const dispatchWorkflow = process.env.ATOMA_DISPATCH_WORKFLOW ?? "atoma-runner.yml";
  const { code, stdout, stderr } = gh(
    "workflow", "run", dispatchWorkflow,
    "--field", `agent=${agent}`,
    "--field", `number=${prNumber}`,
    "--field", "type=pr",
    "--field", `notify=${(process.env.ISSUE_NOTIFY ?? "").trim()}`,
  );
  if (code) {
    log(`dispatchPostPrAgent: WARN failed to dispatch ${agent} for PR #${prNumber}: ${stderr || stdout}`);
  } else {
    log(`dispatchPostPrAgent: dispatched ${agent} for PR #${prNumber}`);
    logDispatch("pr", agent, { number: prNumber });
  }
}

function createPr(a: z.infer<typeof CREATE_PR_SCHEMA>): McpToolResult {
  const title = a.title;
  let body = a.body ?? "";
  const base = a.base;
  body = injectParentIssue(body);
  log(`createPr: title=${JSON.stringify(title)}, base=${JSON.stringify(base)}, REPO=${JSON.stringify(REPO)}`);

  const branch = resolveBranch();
  log(`createPr: resolved branch=${JSON.stringify(branch)}`);

  const worktree = gitRun("status", "--porcelain");
  if (worktree.code) mcpFail(worktree.stderr || worktree.stdout);
  if (worktree.stdout.trim()) {
    mcpFail("Cannot create a PR with uncommitted changes. Call github__commit_and_push first.");
  }
  const head = gitRun("rev-parse", "HEAD");
  if (head.code) mcpFail(`Cannot resolve local HEAD: ${head.stderr || head.stdout}`);
  const remote = gitRun("ls-remote", "--heads", "origin", `refs/heads/${branch}`);
  if (remote.code) mcpFail(`Cannot inspect remote branch '${branch}': ${remote.stderr || remote.stdout}`);
  const remoteHead = remote.stdout.trim().split(/\s+/, 1)[0] ?? "";
  if (!remoteHead) {
    mcpFail(`Remote branch '${branch}' does not exist. Call github__commit_and_push before creating the PR.`);
  }
  if (remoteHead !== head.stdout.trim()) {
    mcpFail(
      `Remote branch '${branch}' is not at local HEAD. Call github__sync_branch and inspect its status; ` +
      `if it reports 'ahead', call github__commit_and_push before creating the PR.`,
    );
  }

  const cmd = ["pr", "create", "--repo", REPO, "--title", title, "--head", branch];
  if (body) cmd.push("--body", body);
  if (base) cmd.push("--base", base);
  log(`createPr: running gh ${cmd.join(" ")}`);
  const { code, stdout, stderr } = gh(...cmd);
  log(`createPr: gh pr create rc=${code}, out=${JSON.stringify(stdout)}, err=${JSON.stringify(stderr)}`);
  if (code) mcpFail(`gh pr create failed (rc=${code}): ${stderr || stdout}`);

  const num = Number(stdout.trim().split("/").pop());
  if (!Number.isFinite(num)) mcpFail(`gh pr create: unexpected output: ${stdout.slice(0, 300)}`);

  logOp("create_pr", { number: num, title });
  dispatchPostPrAgent(num);

  // Traceability: the reviewer dispatch above is fire-and-forget, and (since
  // this call now ends the session immediately, see the returned
  // meta.session_ends below) no further agent text will be posted on the
  // CURRENT issue about this -- record it here explicitly, the same way
  // dispatchSubAgent always confirms its own dispatch with a comment.
  const currentIssue = (process.env.ISSUE_NUMBER ?? "").trim();
  if (currentIssue) {
    gh(
      "issue", "comment", currentIssue, "--repo", REPO,
      "--body", `${LLM_CONTEXT_TAG.write("exclude")}\nAtoma: PR #${num} created (${stdout.trim()}). Dispatching reviewer.`,
    );
  }

  // From the calling agent's (engineer's) perspective, create_pr should
  // behave like launch_sub_agent: a normal-looking synchronous tool call
  // that, once it returns, immediately ends this session. The agent is
  // re-invoked later (see dispatchPostMergeAgent) once the PR actually
  // concludes (merged, or sent back via changes_requested), at which point
  // that re-invocation is framed as the deferred continuation of this exact
  // call -- not a brand-new unrelated task. This keeps the engineer's own
  // run from continuing to execute concurrently with the reviewer run just
  // dispatched above (the whole point of the "serial" design).
  return { text: JSON.stringify({ number: num, url: stdout.trim() }), meta: { session_ends: true } };
}

function commitAndPush(a: z.infer<typeof COMMIT_AND_PUSH_SCHEMA>): string {
  const message = a.message;
  {
    const { code, stdout, stderr } = gitRun("add", "-A");
    if (code) mcpFail(stderr || stdout);
  }
  {
    const { code, stdout, stderr } = gitRun("commit", "-m", message);
    if (code) mcpFail(stderr || stdout);
  }
  const branch = resolveBranch();
  {
    const { code, stdout, stderr } = gitRun("push", "-u", "origin", branch);
    if (code) mcpFail(stderr || stdout);
  }
  logOp("commit_and_push", {});
  return JSON.stringify({ ok: true });
}

function syncBranch(a: z.infer<typeof SYNC_BRANCH_SCHEMA>): string {
  const branch = a.branch?.trim() || resolveBranch();
  const valid = gitRun("check-ref-format", "--branch", branch);
  if (valid.code) mcpFail(`Invalid branch name '${branch}': ${valid.stderr || valid.stdout}`);
  const current = gitRun("branch", "--show-current");
  if (current.code) mcpFail(current.stderr || current.stdout);
  if (current.stdout.trim() !== branch) {
    mcpFail(`Cannot synchronize '${branch}' while '${current.stdout.trim() || "detached HEAD"}' is checked out.`);
  }

  const worktree = gitRun("status", "--porcelain");
  if (worktree.code) mcpFail(worktree.stderr || worktree.stdout);
  if (worktree.stdout.trim()) {
    mcpFail("Cannot synchronize a branch with uncommitted changes. Commit or discard them first.");
  }

  const remoteRef = `refs/remotes/origin/${branch}`;
  const fetch = gitRun("fetch", "origin", `refs/heads/${branch}:${remoteRef}`);
  if (fetch.code) {
    if (/couldn't find remote ref|not our ref/i.test(fetch.stderr)) {
      return JSON.stringify({ branch, status: "remote_missing", ahead: 0, behind: 0 });
    }
    mcpFail(`Failed to fetch remote branch '${branch}': ${fetch.stderr || fetch.stdout}`);
  }

  const counts = gitRun("rev-list", "--left-right", "--count", `HEAD...${remoteRef}`);
  if (counts.code) mcpFail(`Failed to compare branch '${branch}': ${counts.stderr || counts.stdout}`);
  const [ahead, behind] = counts.stdout.trim().split(/\s+/).map(Number);
  if (!Number.isFinite(ahead) || !Number.isFinite(behind)) {
    mcpFail(`Unexpected rev-list output for branch '${branch}': ${counts.stdout}`);
  }

  if (ahead === 0 && behind! > 0) {
    const fastForward = gitRun("merge", "--ff-only", remoteRef);
    if (fastForward.code) mcpFail(`Failed to fast-forward branch '${branch}': ${fastForward.stderr || fastForward.stdout}`);
    logOp("sync_branch", { branch, status: "fast_forwarded", ahead, behind });
    return JSON.stringify({ branch, status: "fast_forwarded", ahead, behind });
  }

  const status = ahead! > 0 && behind! > 0 ? "diverged" : ahead! > 0 ? "ahead" : "up_to_date";
  logOp("sync_branch", { branch, status, ahead, behind });
  return JSON.stringify({ branch, status, ahead, behind });
}

function getPr(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  return JSON.stringify(ghJsonOrThrow("pr", "view", String(a.number), "--repo", REPO, "--json", "number,title,body,state,baseRefName,headRefName,createdAt"));
}

function getPrDiff(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  const { code, stdout, stderr } = gh("pr", "diff", String(a.number), "--repo", REPO);
  if (code) mcpFail(stderr || stdout);
  return stdout.slice(0, 50000);
}

function listPrs(a: z.infer<typeof LIST_PRS_SCHEMA>): string {
  const state = a.state ?? "open";
  const limit = a.limit ?? 30;
  return JSON.stringify(ghJsonOrThrow("pr", "list", "--repo", REPO, "--state", state, "--limit", String(limit), "--json", "number,title,state,headRefName,baseRefName") ?? []);
}

function searchCode(a: z.infer<typeof SEARCH_CODE_SCHEMA>): string {
  const { code, stdout, stderr } = gh("search", "code", a.query, "--repo", REPO, "--limit", "30");
  if (code) mcpFail(stderr || stdout);
  return stdout.slice(0, 50000);
}

function getBranch(a: z.infer<typeof GET_BRANCH_SCHEMA>): string {
  return JSON.stringify(ghJsonOrThrow("api", `repos/${REPO}/branches/${a.name}`));
}

function getCheckRuns(a: z.infer<typeof GET_CHECK_RUNS_SCHEMA>): string {
  const d = ghJsonOrThrow<{ check_runs?: unknown[] }>("api", `repos/${REPO}/commits/${a.ref}/check-runs`);
  return JSON.stringify(d?.check_runs ?? []);
}

function getPrReviews(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  const d = ghJsonOrThrow<{ reviews?: unknown[] }>("pr", "view", String(a.number), "--repo", REPO, "--json", "reviews");
  return JSON.stringify(d?.reviews ?? []);
}

function listPrReviewComments(a: z.infer<typeof NUMBER_ARG_SCHEMA>): string {
  return JSON.stringify(ghJsonOrThrow(`api`, `repos/${REPO}/pulls/${a.number}/comments`) ?? []);
}

function submitPrReview(a: z.infer<typeof SUBMIT_PR_REVIEW_SCHEMA>): string {
  let event: string = a.event;
  if (event === "APPROVE") {
    // GitHub always rejects self-approval since all Atoma agents share the
    // same bot identity ("Can not approve your own pull request"). Rewrite
    // to COMMENT instead of letting the gh call fail.
    log(`submitPrReview: rewriting event APPROVE -> COMMENT for PR #${a.number} (self-approval is never possible)`);
    event = "COMMENT";
  }
  const cmd = ["pr", "review", String(a.number), "--repo", REPO, "--" + event.toLowerCase()];
  if (a.body) cmd.push("--body", a.body);
  const { code, stdout, stderr } = gh(...cmd);
  if (code) mcpFail(stderr || stdout);
  logOp("submit_pr_review", { number: a.number, event });
  return JSON.stringify({ ok: true });
}

/**
 * After a PR merges, re-invoke the agent that originally created it (tagged
 * via <!-- atoma:origin-agent=... --> in the PR body, see injectParentIssue)
 * on the linked sub-issue, instead of silently closing the sub-issue
 * ourselves. Returns true if the dispatch was sent (best-effort; a failure
 * here should not fail merge_pr itself -- caller falls back to closing
 * directly).
 */
/** True if `number` is currently closed (used to skip a pointless post-merge re-invocation when native "Closes #N" auto-close already did the job). */
function isIssueClosed(number: number): boolean {
  const d = ghJsonOrThrow<{ state?: string }>("issue", "view", String(number), "--repo", REPO, "--json", "state");
  return (d?.state ?? "").toUpperCase() === "CLOSED";
}

function dispatchPostMergeAgent(subIssueNum: number, agent: string): boolean {
  const notify = resolveNotify(REPO, subIssueNum);
  {
    const { code, stdout, stderr } = gh(
      "issue", "comment", String(subIssueNum), "--repo", REPO,
      "--body", "Atoma: Your PR was merged. Please confirm completion and close this sub-task.",
    );
    if (code) {
      log(`dispatchPostMergeAgent: could not post trigger comment on #${subIssueNum}: ${stderr || stdout}`);
      return false;
    }
  }
  const { code, stdout, stderr } = gh(
    "workflow", "run", "atoma-runner.yml",
    "--repo", REPO,
    "--field", `agent=${agent}`,
    "--field", `number=${subIssueNum}`,
    "--field", "type=issue",
    "--field", `notify=${notify}`,
  );
  if (code) {
    log(`dispatchPostMergeAgent: gh workflow run failed for #${subIssueNum} (rc=${code}): ${stderr || stdout}`);
    return false;
  }
  log(`dispatchPostMergeAgent: re-invoked ${agent} on #${subIssueNum} to confirm and close`);
  logDispatch("issue", agent, { number: subIssueNum });
  return true;
}

async function mergePr(a: z.infer<typeof NUMBER_ARG_SCHEMA>): Promise<string> {
  const num = a.number;
  const policy = getMergePolicy();
  if (policy !== "auto") {
    log(`mergePr: merge_policy=${JSON.stringify(policy)}, not 'auto' — skipping merge for PR #${num}`);
    return JSON.stringify({ merged: false, reason: `merge_policy is '${policy}', not 'auto'` });
  }
  const { code, stdout, stderr } = gh("pr", "merge", String(num), "--repo", REPO, "--squash");
  log(`mergePr: gh pr merge rc=${code}, out=${JSON.stringify(stdout)}, err=${JSON.stringify(stderr)}`);
  if (code) mcpFail(`gh pr merge failed (rc=${code}): ${stderr || stdout}`);
  logOp("merge_pr", { number: num });

  const d = ghJsonOrThrow<{ body?: string }>("pr", "view", String(num), "--repo", REPO, "--json", "body");
  const body = d?.body ?? "";
  const parentIssue = PARENT_ISSUE_TAG.read(body);

  const handoff = decidePostMergeHandoff({
    parentIssue,
    parentAlreadyClosed: parentIssue !== undefined && isIssueClosed(parentIssue),
    originAgent: ORIGIN_AGENT_TAG.read(body),
  });

  switch (handoff.kind) {
    case "no-parent":
      return JSON.stringify({ merged: true, closed_issue: null });
    case "already-closed":
      log(`mergePr: parent issue #${handoff.parentIssue} already closed -- skipping post-merge re-invocation`);
      return JSON.stringify({ merged: true, closed_issue: null });
    case "reinvoke-origin-agent":
      if (dispatchPostMergeAgent(handoff.parentIssue, handoff.agent)) {
        return JSON.stringify({ merged: true, closed_issue: null, reinvoked_agent: handoff.agent });
      }
      // The preferred handoff (re-invoking the origin agent) failed to
      // dispatch -- fall back to closing the parent directly ourselves,
      // same as the "close-directly" case below.
      return await closeParentAndReport(handoff.parentIssue);
    case "close-directly":
      return await closeParentAndReport(handoff.parentIssue);
  }
}

/** closeIssueAndDispatch also triggers phase-gating/aggregation itself. Shared by mergePr()'s "close-directly" case and its "reinvoke failed" fallback. */
async function closeParentAndReport(parentIssue: number): Promise<string> {
  try {
    await closeIssueAndDispatch({ number: parentIssue });
    return JSON.stringify({ merged: true, closed_issue: parentIssue });
  } catch (e) {
    log(`mergePr: could not close parent issue #${parentIssue}: ${e}`);
    return JSON.stringify({ merged: true, closed_issue: null });
  }
}

const { tools: TOOLS, dispatch } = buildMcpTools([
  defineMcpTool({
    name: "create_issue",
    description: "Create a GitHub issue in the current repository and return its number and URL. Use this for durable work items, especially delegated child tasks; sub_issue defaults to true and links the new issue to the current issue. This mutates GitHub and records the operation in Atoma's audit log.",
    schema: CREATE_ISSUE_SCHEMA,
    handler: createIssue,
  }),
  defineMcpTool({ name: "get_issue", description: "Retrieve one issue's title, body, state, labels, timestamps, and comments by issue number. Use this when full issue context is needed; for scanning multiple issues, use list_issues instead. Returns a JSON issue object and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: getIssue }),
  defineMcpTool({ name: "list_issues", description: "List issue summaries in the current repository, optionally filtered by state and labels. Use this to discover or scan issues; use get_issue when full body and comments are needed. Returns a JSON array and does not mutate GitHub.", schema: LIST_ISSUES_SCHEMA, handler: listIssues }),
  defineMcpTool({ name: "get_issue_comments", description: "Retrieve only the comments for one issue. Use this when conversation history is needed without the rest of the issue payload. Returns a JSON array in chronological GitHub order and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: getIssueComments }),
  defineMcpTool({ name: "close_issue", description: "Close a bot-created issue and trigger Atoma parent-task aggregation when applicable. Use only after the issue's work is complete; the tool refuses to close human-created issues. Returns JSON success status and mutates GitHub.", schema: NUMBER_ARG_SCHEMA, handler: closeIssueAndDispatch }),
  defineMcpTool({ name: "create_pr", description: "Create a pull request from the checked-out Atoma branch and return its number and URL. Call commit_and_push first: this tool requires a clean worktree and exact local/remote HEAD equality, and it never pushes for you. On success it dispatches the configured reviewer and ends the current agent session.", schema: CREATE_PR_SCHEMA, handler: createPr }),
  defineMcpTool({ name: "get_pr", description: "Retrieve one pull request's metadata, including state and base/head branches. Use this for PR status and identity; use get_pr_diff or review tools for code and review details. Returns a JSON object and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: getPr }),
  defineMcpTool({ name: "get_pr_diff", description: "Retrieve the unified diff for one pull request, truncated to 50,000 characters. Use this to review code changes; it does not include review conversations. Returns plain diff text and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: getPrDiff }),
  defineMcpTool({ name: "list_prs", description: "List pull request summaries in the current repository, optionally filtered by state. Use this to discover PRs; use get_pr for full metadata. Returns a JSON array and does not mutate GitHub.", schema: LIST_PRS_SCHEMA, handler: listPrs }),
  defineMcpTool({ name: "search_code", description: "Search code through GitHub within the current repository. Use this for remote repository text or symbol discovery when local filesystem search is unavailable; do not use it for uncommitted changes. Returns GitHub CLI search text, truncated to 50,000 characters.", schema: SEARCH_CODE_SCHEMA, handler: searchCode }),
  defineMcpTool({ name: "get_branch", description: "Retrieve GitHub's branch metadata for an exact branch name. Use this to inspect remote branch identity and protection information, not local worktree state. Returns a JSON branch object and does not mutate GitHub.", schema: GET_BRANCH_SCHEMA, handler: getBranch }),
  defineMcpTool({
    name: "sync_branch",
    description: "Synchronize the checked-out branch with its remote counterpart and report ahead/behind status. Use this after a non-fast-forward push failure or before retrying branch publication; it fast-forwards only when safe. It never rebases or force-pushes, and reports diverged branches for explicit resolution.",
    schema: SYNC_BRANCH_SCHEMA,
    handler: syncBranch,
  }),
  defineMcpTool({ name: "get_check_runs", description: "Retrieve GitHub Actions and other check runs for a commit, branch, or tag. Use this to verify CI status after pushing or before merge decisions. Returns a JSON array of check-run objects and does not wait for incomplete checks.", schema: GET_CHECK_RUNS_SCHEMA, handler: getCheckRuns }),
  defineMcpTool({ name: "get_pr_reviews", description: "Retrieve submitted review summaries for one pull request. Use this to inspect review decisions and bodies; use list_pr_review_comments for line-level code comments. Returns a JSON array and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: getPrReviews }),
  defineMcpTool({ name: "list_pr_review_comments", description: "Retrieve line-level review comments for one pull request. Use this to find file- and line-specific feedback; use get_pr_reviews for overall review decisions. Returns a JSON array and does not mutate GitHub.", schema: NUMBER_ARG_SCHEMA, handler: listPrReviewComments }),
  defineMcpTool({
    name: "submit_pr_review",
    description: "Submit a pull request review as either a general COMMENT or REQUEST_CHANGES. Use this after inspecting the diff and checks; APPROVE is intentionally unavailable because all Atoma agents share the PR author's bot identity. This mutates GitHub and returns JSON success status.",
    schema: SUBMIT_PR_REVIEW_SCHEMA,
    handler: submitPrReview,
  }),
  defineMcpTool({
    name: "commit_and_push",
    description: "Stage all worktree changes, create one commit, and push the checked-out branch to origin. Use this after validation and before create_pr; do not call it with unrelated or unreviewed changes present. Returns JSON success status and fails rather than rewriting remote history.",
    schema: COMMIT_AND_PUSH_SCHEMA,
    handler: commitAndPush,
  }),
  defineMcpTool({
    name: "merge_pr",
    description: "Merge a pull request only when config.json sets merge_policy to 'auto', then continue Atoma's issue handoff. Call this after review feedback is posted and checks are acceptable; under manual or unknown policy it performs no merge and returns merged:false. This may merge the PR, close its linked issue, and dispatch follow-up work.",
    schema: NUMBER_ARG_SCHEMA,
    handler: mergePr,
  }),
]);

const server = new Server(
  { name: "atoma-github-mcp", version: "1.0.0" },
  { capabilities: { tools: {} } },
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: TOOLS }));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args = {} } = request.params;
  try {
    const { text, meta } = await dispatch(name, args);
    return {
      content: [{ type: "text", text }],
      isError: false,
      ...(meta ? { _meta: meta } : {}),
    };
  } catch (e) {
    log(`Tool error: ${e}`);
    return { content: [{ type: "text", text: `Error: ${(e as Error).message ?? e}` }], isError: true };
  }
});

async function main(): Promise<void> {
  log(`Starting for ${REPO}`);
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

if (import.meta.main) void main();

#!/usr/bin/env bun
/**
 * atoma.ts — MCP server exposing Atoma orchestration tools.
 *
 * Transport: stdio, via the official @modelcontextprotocol/sdk.
 *
 * Tools:
 *   - launch_sub_agent: Launch Atoma agents on sub-issues and end the
 *     orchestrator session.
 *   - request_close_issue: Conclude work on the current issue.
 *
 * Both tool responses include `_meta.session_ends: true` so the Atoma core
 * can detect that the session should terminate.
 *
 * IMPORTANT: this process's `process.stdout` IS the JSON-RPC transport --
 * never `console.log()` anywhere in this file or in anything it calls
 * in-process (dispatchSubAgent/concludeIssue and whatever they import);
 * always `console.error()` (stderr) for logging.
 */
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { gh } from "../../../../lib/gh.ts";
import { dispatchSubAgent } from "../lib/dispatch_sub_agent.ts";
import { LLM_CONTEXT_TAG } from "../../../../lib/tags.ts";
import { concludeIssue } from "../lib/conclude_issue.ts";
import { buildMcpTools, defineMcpTool, z, type McpToolResult } from "../../../../lib/mcp-tool.ts";

function log(msg: string): void {
  console.error(`[atoma-mcp] ${msg}`);
}

const LAUNCH_SUB_AGENT_SCHEMA = z.object({
  tasks: z
    .array(
      z.object({
        issue: z.number().int().positive().describe("The sub-issue number."),
        agent: z.string().min(1).describe("The agent to dispatch (e.g., 'engineer')."),
      }),
    )
    .min(1, "tasks must be a non-empty list of {issue, agent} objects")
    .describe("List of {issue, agent} pairs to dispatch."),
});

const REQUEST_CLOSE_ISSUE_SCHEMA = z.object({
  reason: z.string().min(1).describe("Why this issue's work is considered complete."),
  summary: z.string().optional().describe("Final summary to include in the posted comment (e.g. an aggregation report)."),
});

function mcpFail(message: string): never {
  throw new Error(message);
}

function handleLaunchSubAgent(args: z.infer<typeof LAUNCH_SUB_AGENT_SCHEMA>): McpToolResult {
  const validTasks = args.tasks;

  log(`Dispatching ${validTasks.length} sub-issue(s): ${JSON.stringify(validTasks)}`);

  // The orchestrator's OWN current issue (the parent, from the sub-issues'
  // point of view).
  const parentIssue = (process.env.ISSUE_NUMBER ?? "").trim();
  const notify = process.env.ISSUE_NOTIFY ?? "";

  const dispatched: string[] = [];
  const errors: string[] = [];

  for (const { issue, agent } of validTasks) {
    try {
      dispatchSubAgent(issue, agent, notify);
      dispatched.push(`#${issue}→${agent}`);
    } catch (e) {
      const message = (e as Error).message ?? String(e);
      log(`dispatchSubAgent failed for #${issue}: ${message}`);
      errors.push(`#${issue}/${agent}: ${message}`);
    }
  }

  // Best-effort comment on the PARENT issue so a human reading the parent's
  // thread has a full audit trail of what was dispatched.
  if (dispatched.length && parentIssue) {
    const bodyLines = [LLM_CONTEXT_TAG.write("exclude"), "Atoma: Launched sub-agent(s):", ...dispatched.map((d) => `- ${d}`)];
    gh("issue", "comment", parentIssue, "--body", bodyLines.join("\n"));
  }

  if (errors.length && !dispatched.length) {
    mcpFail(`All dispatches failed: ${errors.join("; ")}`);
  }

  const summaryLines = [`Dispatch comments posted for ${dispatched.length} sub-issue(s): ${dispatched.join(", ")}.`];
  if (errors.length) summaryLines.push(`Warning: ${errors.length} failed: ${errors.join("; ")}`);
  summaryLines.push("");
  summaryLines.push("Agents will be dispatched automatically. The orchestrator session will now end.");
  summaryLines.push("It will resume automatically when all sub-issues are closed.");

  return { text: summaryLines.join("\n"), meta: { session_ends: true } };
}

async function handleRequestCloseIssue(args: z.infer<typeof REQUEST_CLOSE_ISSUE_SCHEMA>): Promise<McpToolResult> {
  const reason = args.reason.trim();
  const summary = (args.summary ?? "").trim();

  if (!reason) mcpFail("reason must be a non-empty string");

  const issueNumberRaw = (process.env.ISSUE_NUMBER ?? "").trim();
  if (!issueNumberRaw) mcpFail("ISSUE_NUMBER is not set in the environment");
  const issueNumber = Number(issueNumberRaw);

  log(`Concluding issue #${issueNumber}: reason=${JSON.stringify(reason)}`);

  let result: { outcome: "closed" | "escalated" };
  try {
    result = await concludeIssue(issueNumber, reason, summary);
  } catch (e) {
    const message = (e as Error).message ?? String(e);
    log(`concludeIssue failed for #${issueNumber}: ${message}`);
    mcpFail(`Failed to conclude issue #${issueNumber}: ${message}`);
  }

  const text =
    result.outcome === "closed"
      ? `Issue #${issueNumber} was created by an Atoma agent (a sub-issue) and has been closed automatically. Phase-gating/aggregation for its parent has been checked.`
      : `Issue #${issueNumber} was opened directly by a human. It has NOT been closed automatically -- a comment mentioning them was posted with your reason/summary, asking them to review and close it themselves.`;

  return { text, meta: { session_ends: true } };
}

const { tools: TOOLS, dispatch } = buildMcpTools([
  defineMcpTool({
    name: "launch_sub_agent",
    description:
      "Dispatch Atoma agents onto sub-issues and immediately end the orchestrator session. " +
      "Call this ONCE after creating all sub-issues via GitHub MCP. " +
      "Each sub-issue can be assigned a different agent. " +
      "The orchestrator session ends immediately after this call returns. " +
      "The orchestrator will be automatically re-invoked when ALL sub-issues are closed.",
    schema: LAUNCH_SUB_AGENT_SCHEMA,
    handler: handleLaunchSubAgent,
  }),
  defineMcpTool({
    name: "request_close_issue",
    description:
      "Conclude work on YOUR CURRENT issue and end your session. This is the ONLY " +
      "correct way for the orchestrator to finish an issue -- do NOT call " +
      "github__close_issue yourself, and do NOT just stop responding without calling " +
      "this. The tool decides what happens next based on who opened THIS issue: " +
      "if it was created by another Atoma agent (a sub-issue), it is closed " +
      "automatically right now and phase-gating/aggregation is triggered for its " +
      "parent. If it was opened directly by a human (a root issue), it is NOT " +
      "closed -- instead a comment mentioning that human is posted with your reason " +
      "and summary, asking them to review and close it themselves.",
    schema: REQUEST_CLOSE_ISSUE_SCHEMA,
    handler: handleRequestCloseIssue,
  }),
]);

const server = new Server(
  { name: "atoma-mcp-server", version: "1.0.0" },
  { capabilities: { tools: {} } },
);

server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools: TOOLS }));

server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args = {} } = request.params;
  try {
    const { text, meta } = await dispatch(name, args);
    return {
      content: [{ type: "text", text }],
      isError: false,
      ...(meta ? { _meta: meta } : {}),
    };
  } catch (e) {
    log(`Handler error for ${name}: ${(e as Error).message}`);
    return { content: [{ type: "text", text: `Error: ${(e as Error).message}` }], isError: true };
  }
});

async function main(): Promise<void> {
  log("Starting atoma-mcp-server (stdio transport)");
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

if (import.meta.main) void main();

#!/usr/bin/env bun
/**
 * build-dist.ts — Bundles every deployable entry-point script (via
 * `Bun.build`) from its `src/` source into the mirrored `dist/.github/`
 * location:
 *   - `src/scripts/**` (this repo's own workflow-automation glue, invoked
 *     directly from a `*.wac.ts` file's `run:` step) -> `dist/.github/scripts/`.
 *   - `src/atoma/tools/scripts/**` (Atoma's own MCP servers, `before_tool`
 *     hook, and the one-shot scripts they use) -> `dist/.github/atoma/tools/scripts/`.
 *   - Atoma's static, non-code content (`config.json`, `prompt-template.md`,
 *     agent definitions, recursive skill Markdown, and `tools/tools.yaml`) ->
 *     `dist/.github/atoma/`,
 *     copied verbatim (nothing to bundle).
 *
 * Every entry point is bundled with ALL of its imports inlined -- including
 * the shared `src/lib/**` kernel (so `src/scripts/**` and
 * `src/atoma/tools/scripts/**` can freely import shared code without any
 * hand-duplicated files between them) and npm dependencies like
 * `@modelcontextprotocol/sdk`/`shell-quote` (so the deployed output needs no
 * `node_modules`/`package.json`/`bun install` step at all -- verified: a
 * bundled `mcp/github.ts` runs standalone with zero dependencies nearby).
 * Bundled output keeps a `.ts` extension (Bun happily runs plain JS through
 * a `.ts`-named file) so every existing `bun run .github/.../foo.ts`
 * reference -- in generated workflow YAML, `tools.yaml`, `ScriptRef`'s
 * runtime-path derivation -- needs no change.
 *
 * `.test.ts` files are excluded from entry-point discovery -- tests are a
 * dev-time concern for this repo, not something end users need in their
 * own `.github/`. `dist/.github/` is fully generated output: nothing under
 * it should ever be hand-edited directly.
 */
import { cpSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC_DIR = join(REPO_ROOT, "src");
const DIST_GITHUB_DIR = join(REPO_ROOT, "dist", ".github");

/** Recursively collects every entry-point `*.ts` file under `dir`, skipping `excludeDirs` (by name, at any depth) and `*.test.ts` files. */
function collectEntryPoints(dir: string, excludeDirs: ReadonlySet<string>): string[] {
  const results: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (excludeDirs.has(entry.name)) continue;
      results.push(...collectEntryPoints(join(dir, entry.name), excludeDirs));
    } else if (entry.isFile() && entry.name.endsWith(".ts") && !entry.name.endsWith(".test.ts")) {
      results.push(join(dir, entry.name));
    }
  }
  return results;
}

/** Bundles every entry point under `srcDir` into `distDir`, preserving its subdirectory structure (e.g. `mcp/github.ts` -> `<distDir>/mcp/github.ts`). */
async function bundleTree(srcDir: string, distDir: string, excludeDirs: ReadonlySet<string> = new Set()): Promise<void> {
  const entrypoints = collectEntryPoints(srcDir, excludeDirs);
  rmSync(distDir, { recursive: true, force: true });

  // Build each deployable entry point independently. Imported implementation
  // modules live under excluded `lib/` directories and are inlined here.
  for (const entrypoint of entrypoints) {
    const result = await Bun.build({
      entrypoints: [entrypoint],
      outdir: distDir,
      root: srcDir,
      target: "bun",
      format: "esm",
      naming: "[dir]/[name].ts",
    });
    if (!result.success) {
      console.error(`build-dist: bundling failed for ${entrypoint}:`);
      for (const log of result.logs) console.error(log);
      process.exit(1);
    }
  }

  console.log(`build-dist: bundled ${entrypoints.length} script(s): ${srcDir} -> ${distDir}`);
}

function copyDirectoryFresh(source: string, destination: string): void {
  rmSync(destination, { recursive: true, force: true });
  cpSync(source, destination, { recursive: true });
}

function copyStaticAtomaContent(): void {
  const srcAtomaDir = join(SRC_DIR, "atoma");
  const distAtomaDir = join(DIST_GITHUB_DIR, "atoma");

  for (const file of ["config.json", "prompt-template.md"]) {
    cpSync(join(srcAtomaDir, file), join(distAtomaDir, file));
  }
  copyDirectoryFresh(join(srcAtomaDir, "agent-definitions"), join(distAtomaDir, "agent-definitions"));
  copyDirectoryFresh(join(srcAtomaDir, "skills"), join(distAtomaDir, "skills"));
  mkdirSync(join(distAtomaDir, "tools"), { recursive: true });
  cpSync(join(srcAtomaDir, "tools", "tools.yaml"), join(distAtomaDir, "tools", "tools.yaml"));

  console.log(`build-dist: copied static content: ${srcAtomaDir} -> ${distAtomaDir}`);
}

async function main(): Promise<void> {
  await bundleTree(join(SRC_DIR, "scripts"), join(DIST_GITHUB_DIR, "scripts"), new Set(["lib", "testing"]));
  await bundleTree(
    join(SRC_DIR, "atoma", "tools", "scripts"),
    join(DIST_GITHUB_DIR, "atoma", "tools", "scripts"),
    new Set(["lib"]),
  );
  copyStaticAtomaContent();
}

void main();

#!/usr/bin/env bun
/** Foreground-only shell MCP server for deterministic agent validation commands. */
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { CallToolRequestSchema, ListToolsRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { buildMcpTools, defineMcpTool, z } from "../../../../lib/mcp-tool.ts";

const MAX_OUTPUT_BYTES = 1_000_000;

const SHELL_EXECUTE_SCHEMA = z.object({
  command: z.string().min(1).describe("Shell command to execute with bash."),
  working_directory: z.string().optional().describe("Directory in which to run the command. Defaults to the server working directory."),
  environment_variables: z.record(z.string()).optional().describe("Environment variables to add or override for this command."),
  input_data: z.string().optional().describe("Text to provide on standard input."),
  timeout_seconds: z.number().int().min(1).max(3600).optional().default(300).describe("Maximum foreground execution time in seconds. Defaults to 300."),
  execution_mode: z.literal("foreground").optional().default("foreground").describe("Only foreground execution is supported."),
});

async function executeShell(args: z.infer<typeof SHELL_EXECUTE_SCHEMA>): Promise<string> {
  const startedAt = Date.now();
  const child = Bun.spawn(["bash", "-lc", args.command], {
    cwd: args.working_directory ?? process.cwd(),
    env: { ...process.env, ...args.environment_variables },
    stdin: args.input_data === undefined ? "ignore" : "pipe",
    stdout: "pipe",
    stderr: "pipe",
  });

  if (args.input_data !== undefined) {
    if (!child.stdin) throw new Error("Shell process stdin is unavailable");
    child.stdin.write(args.input_data);
    child.stdin.end();
  }

  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    child.kill();
  }, args.timeout_seconds * 1000);

  const [exitCode, stdout, stderr] = await Promise.all([
    child.exited,
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
  ]).finally(() => clearTimeout(timer));

  const truncate = (value: string): { text: string; truncated: boolean } => {
    const bytes = Buffer.from(value);
    return bytes.length <= MAX_OUTPUT_BYTES
      ? { text: value, truncated: false }
      : { text: bytes.subarray(0, MAX_OUTPUT_BYTES).toString("utf8"), truncated: true };
  };
  const out = truncate(stdout);
  const err = truncate(stderr);

  return JSON.stringify({
    status: timedOut ? "timeout" : exitCode === 0 ? "completed" : "failed",
    exit_code: exitCode,
    stdout: out.text,
    stderr: err.text,
    output_truncated: out.truncated || err.truncated,
    execution_time_ms: Date.now() - startedAt,
  });
}

const { tools, dispatch } = buildMcpTools([
  defineMcpTool({
    name: "shell_execute",
    description: "Execute one foreground bash command and return its exit code, stdout, stderr, and duration. Use this for tests, builds, linting, and focused read-only inspection. Set timeout_seconds for commands that may run longer than five minutes. Git and GitHub mutations remain blocked by the configured hook.",
    schema: SHELL_EXECUTE_SCHEMA,
    handler: executeShell,
  }),
]);

const server = new Server({ name: "atoma-shell-mcp", version: "1.0.0" }, { capabilities: { tools: {} } });
server.setRequestHandler(ListToolsRequestSchema, async () => ({ tools }));
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args = {} } = request.params;
  try {
    const { text } = await dispatch(name, args);
    return { content: [{ type: "text", text }], isError: false };
  } catch (error) {
    return { content: [{ type: "text", text: `Error: ${(error as Error).message ?? error}` }], isError: true };
  }
});

async function main(): Promise<void> {
  await server.connect(new StdioServerTransport());
}

if (import.meta.main) void main();

/**
 * aggregation.ts — the ONE canonical implementation of "check whether all
 * sub-issues of an orchestrated parent are done, and if so, dispatch the
 * orchestrator for re-invocation".
 *
 * Three call sites need this exact gate, previously reimplemented
 * independently (with subtly different retry/exclude/idempotency behavior)
 * in dispatch_orchestrator_if_ready.ts (atoma-side, post-close),
 * dispatch_if_siblings_done.ts (workflow-side, manual-close fallback), and
 * aggregate_sub_issues.ts (workflow-side, PR-merge primary path -- which
 * additionally injects sub-issue results into the orchestrator's session
 * before dispatching, via `beforeDispatch` below).
 *
 * Idempotency: two of the three call sites can race for the SAME
 * completion (a PR merge triggers both the event-driven
 * aggregate_sub_issues.ts AND, asynchronously, an origin-agent
 * re-invocation that eventually closes the sub-issue itself and reaches
 * dispatch_orchestrator_if_ready.ts) -- see the `atoma:aggregated` marker
 * check below, which makes whichever caller gets here first win and the
 * other a no-op.
 */
import { gh } from "./gh.ts";
import { countOpenSiblings } from "./sibling-check.ts";
import { resolveNotify } from "./notify.ts";
import { AGGREGATED_TAG, LLM_CONTEXT_TAG, PARENT_TAG, SUB_RESULT_TAG } from "./tags.ts";
import { logDispatch } from "./ops-log.ts";

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export interface DispatchGateOptions {
  repo: string;
  parent: number;
  /** The sub-issue whose completion triggered this check. */
  closedNum: number;
  /**
   * Retry the sibling count with backoff (4 attempts) on GitHub
   * search-index eventual-consistency lag -- needed when called right
   * after OUR OWN close of `closedNum`, before the search index has
   * necessarily caught up.
   */
  retry?: boolean;
  /**
   * Exclude `closedNum` from the sibling count regardless of its live
   * open/closed state -- needed when called from a PR-merge event, where
   * `closedNum` may not be reflected as closed yet at all (native
   * "Closes #N" auto-close is unreliable under the Actions GITHUB_TOKEN).
   */
  exclude?: boolean;
  /** Progress-comment text posted when siblings remain. Omit to post nothing in that case (matches the manual-close fallback's original silent behavior). */
  progressMessage?: (remaining: number) => string;
  /** Run just before posting the "all done" comment + dispatching -- aggregate_sub_issues.ts uses this to inject sub-issue results into the orchestrator's persisted session first. */
  beforeDispatch?: () => Promise<void> | void;
  dispatchWorkflow?: string;
}

export interface DispatchGateResult {
  ready: boolean;
  remaining: number;
  dispatched: boolean;
}

export async function dispatchOrchestratorIfReady(opts: DispatchGateOptions): Promise<DispatchGateResult> {
  const excludeNum = opts.exclude ? opts.closedNum : undefined;
  let remaining = countOpenSiblings({ repo: opts.repo, parent: opts.parent, exclude: excludeNum });

  if (opts.retry) {
    for (let attempt = 1; remaining > 0 && attempt < 4; attempt++) {
      await sleep(2000 * attempt);
      remaining = countOpenSiblings({ repo: opts.repo, parent: opts.parent, exclude: excludeNum });
    }
  }

  if (remaining > 0) {
    if (opts.progressMessage) {
      gh(
        "issue", "comment", String(opts.parent), "--repo", opts.repo,
        "--body", `${LLM_CONTEXT_TAG.write("exclude")}\n${SUB_RESULT_TAG.write(opts.closedNum)}\n${opts.progressMessage(remaining)}`,
      );
    }
    return { ready: false, remaining, dispatched: false };
  }

  const { stdout: commentsOut } = gh(
    "issue", "view", String(opts.parent), "--repo", opts.repo,
    "--json", "comments", "--jq", ".comments[].body",
  );
  if (commentsOut.includes(AGGREGATED_TAG.write(opts.closedNum))) {
    // Another caller already handled this exact completion (see module doc
    // comment for the race this guards against).
    return { ready: true, remaining: 0, dispatched: false };
  }

  if (opts.beforeDispatch) await opts.beforeDispatch();

  gh(
    "issue", "comment", String(opts.parent), "--repo", opts.repo,
    "--body", `${AGGREGATED_TAG.write(opts.closedNum)}\nAtoma: All sub-tasks completed (last: #${opts.closedNum}). Re-invoking orchestrator for aggregation.`,
  );

  const notify = resolveNotify(opts.repo, opts.parent);
  gh(
    "workflow", "run", opts.dispatchWorkflow ?? "atoma-runner.yml",
    "--repo", opts.repo,
    "--field", "agent=orchestrator",
    "--field", `number=${opts.parent}`,
    "--field", "type=issue",
    "--field", `notify=${notify}`,
  );
  logDispatch("issue", "orchestrator", { number: opts.parent });

  return { ready: true, remaining: 0, dispatched: true };
}

/**
 * Resolves `subIssueNum`'s orchestrator parent from its own `atoma:parent`
 * tag, then runs the dispatch gate on it with retry enabled (GitHub's
 * search index is only eventually consistent -- the sub-issue we just
 * closed a moment ago may still be reported as open for a second or two).
 * No-ops (returns `{ready:false,remaining:0,dispatched:false}`) when
 * `subIssueNum` has no parent tag at all (not every closed issue is a
 * tracked Atoma sub-issue).
 *
 * The one canonical "a sub-issue just closed -- is its parent ready?"
 * entry point, used identically by mcp/github.ts's closeIssue() and
 * concludeIssue's bot-authored-issue branch (previously both
 * spawned the now-removed dispatch_orchestrator_if_ready.ts script).
 */
export async function dispatchOrchestratorIfSubIssueReady(repo: string, subIssueNum: number): Promise<DispatchGateResult> {
  const { code, stdout } = gh("issue", "view", String(subIssueNum), "--repo", repo, "--json", "body", "--jq", ".body");
  const body = code === 0 ? stdout : "";
  const parent = PARENT_TAG.read(body);
  if (parent === undefined) {
    console.error(`issue #${subIssueNum} has no atoma:parent tag, nothing to do`);
    return { ready: false, remaining: 0, dispatched: false };
  }
  return dispatchOrchestratorIfReady({ repo, parent, closedNum: subIssueNum, retry: true });
}

#!/usr/bin/env bun
/**
 * post_result_comment.ts — Post the agent's final output as a GitHub
 * comment, including token usage/cost and (when nothing further will
 * happen automatically) a mention.
 *
 * Reads atoma_output.txt (required) and atoma_logs.txt (optional, for the
 * ATOMA_TOKEN_USAGE: line) from the current directory.
 *
 * Usage:
 *   post_result_comment.ts --number N --agent NAME [--notify LOGIN]
 *     [--directive NAME] [--chain-continues true|false]
 *     [--max-iterations-reached true|false] --run-url URL
 * Writes `comment_id=<id>` to $GITHUB_OUTPUT.
 */
import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { gh } from "../lib/gh.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface PostResultCommentArgs {
  number: string | number;
  agent: string;
  notify?: string;
  directive?: string;
  "chain-continues"?: string;
  "max-iterations-reached"?: string;
  "run-url": string;
}

export const ref = defineScript<PostResultCommentArgs>(import.meta.url);

function tokenUsageLines(): string[] {
  if (!existsSync("atoma_logs.txt")) return [];
  const usageLine = readFileSync("atoma_logs.txt", "utf8")
    .split("\n")
    .find((l) => l.includes("ATOMA_TOKEN_USAGE:"));
  if (!usageLine) return [];

  const prompt = /prompt=(\d+)/.exec(usageLine)?.[1];
  const completion = /completion=(\d+)/.exec(usageLine)?.[1];
  const total = /total=(\d+)/.exec(usageLine)?.[1];

  const lines = ["", "---", `_Tokens: ${total ?? "?"} total (${prompt ?? "?"} prompt + ${completion ?? "?"} completion)_`];
  if (prompt && completion) {
    const cost = (Number(prompt) * 0.15) / 1_000_000 + (Number(completion) * 0.6) / 1_000_000;
    lines.push(`_Estimated cost: $${cost.toFixed(4)}_`);
  }
  return lines;
}

export function buildCommentBody(args: {
  agent: string;
  notify?: string;
  directive?: string;
  chainContinues?: string;
  maxIterationsReached?: string;
  runUrl: string;
  output: string;
  usageLines: string[];
}): string {
  const lines = [`<!-- atoma:agent=${args.agent} -->`, args.output, "", ...args.usageLines];

  if (!args.directive && args.chainContinues !== "true" && args.notify) {
    lines.push(
      `@${args.notify} — **${args.agent}** task completed. No agent will be automatically executed next. Please review the results or provide instructions for the next step.`,
      "",
    );
  }

  lines.push("---", `_run by [${args.agent}](${args.runUrl})_`);
  if (args.maxIterationsReached === "true") {
    lines.push(`⚠️ _Max iterations reached. Comment \`/${args.agent}\` to continue._`);
  }

  return lines.join("\n");
}

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      number: { type: "string" },
      agent: { type: "string" },
      notify: { type: "string" },
      directive: { type: "string" },
      "chain-continues": { type: "string" },
      "max-iterations-reached": { type: "string" },
      "run-url": { type: "string" },
    },
  });

  if (!values.number || !values.agent || !values["run-url"]) {
    console.error("usage: post_result_comment.ts --number N --agent NAME --run-url URL [...]");
    process.exit(2);
  }

  const output = existsSync("atoma_output.txt") ? readFileSync("atoma_output.txt", "utf8") : "";

  // `atoma_output.txt` is empty whenever the run ended via a session-ending
  // tool call (launch_sub_agent, request_close_issue, create_pr -- see
  // src/atoma/tools/scripts/mcp/{atoma,github}.ts's `_meta.session_ends`):
  // atoma's own inference loop stops immediately in that case, before the
  // model ever gets a further turn to produce text. Each of those tools
  // already posts its OWN dedicated, meaningful comment (e.g. "Launched
  // sub-agent(s): ...", "PR #N created..."), so posting a second, essentially
  // content-free "run by [agent](url)" comment here on top of that would
  // just be noise -- skip entirely rather than post an empty wrapper.
  if (!output.trim()) {
    console.error("atoma_output.txt is empty (session ended via a tool call) -- skipping result comment.");
    return;
  }

  const body = buildCommentBody({
    agent: values.agent,
    notify: values.notify,
    directive: values.directive,
    chainContinues: values["chain-continues"],
    maxIterationsReached: values["max-iterations-reached"],
    runUrl: values["run-url"],
    output,
    usageLines: tokenUsageLines(),
  });

  const { code, stdout, stderr } = gh(
    "api",
    `repos/${process.env.GITHUB_REPOSITORY}/issues/${values.number}/comments`,
    "--method",
    "POST",
    "-f",
    `body=${body}`,
    "--jq",
    ".id",
  );
  if (code !== 0) {
    throw new Error(`Failed to post result comment: ${stderr || stdout}`);
  }

  const commentId = stdout.trim();
  const githubOutput = process.env.GITHUB_OUTPUT;
  if (githubOutput) appendFileSync(githubOutput, `comment_id=${commentId}\n`);
  console.error(`Posted comment ID: ${commentId}`);
}

if (import.meta.main) main();

/**
 * ops-log.ts — Structured JSON-lines log of mutating operations Atoma
 * performs during a run, written to $ATOMA_OPS_LOG (default
 * /tmp/atoma_ops.log). Two purposes:
 *   1. A general audit trail (create_issue, close_issue, create_pr,
 *      merge_pr, etc. -- see mcp/github.ts's call sites).
 *   2. `logDispatch()`'s `"op":"dispatch"` entries are the canonical,
 *      STRUCTURED signal `atoma-runner.wac.ts`'s `chain_continues`
 *      detection reads (via `grep` for the literal `"op":"dispatch"`
 *      JSON key/value, a stable documented field -- not by pattern-matching
 *      arbitrary human-readable log prose). The previous approach (grepping
 *      stderr log TEXT for hand-written strings like "dispatched: agent=...")
 *      silently broke once already when a refactor changed the wording
 *      without updating the grep pattern to match -- this module exists so
 *      that class of bug can't recur: the dispatch signal now has one
 *      canonical writer and one canonical reader, both referring to the
 *      same `"op":"dispatch"` literal.
 */
import { appendFileSync } from "node:fs";

const OPS_LOG_PATH = process.env.ATOMA_OPS_LOG ?? "/tmp/atoma_ops.log";

export function logOp(op: string, payload: Record<string, unknown> = {}): void {
  const entry = { ts: new Date().toISOString(), op, ...payload };
  try {
    appendFileSync(OPS_LOG_PATH, JSON.stringify(entry) + "\n");
  } catch (e) {
    console.error(`[ops-log] WARN: failed to write op log: ${e}`);
  }
}

/**
 * Records that a follow-up agent dispatch was triggered as a side effect of
 * a tool call during this run: `launch_sub_agent` (once per sub-issue),
 * `create_pr`'s automatic reviewer dispatch, `merge_pr`'s re-invocation of
 * the PR's origin agent (or, once that confirms and closes, the
 * orchestrator), and a sub-issue closure's orchestrator dispatch (see
 * lib/aggregation.ts). This is the ONE canonical "a chain continues"
 * signal every dispatch site writes.
 */
export function logDispatch(target: string, agent: string, extra: Record<string, unknown> = {}): void {
  logOp("dispatch", { target, agent, ...extra });
}

import { Workflow } from "@github-actions-workflow-ts/lib";
import type { PullRequestOpenedEvent, PullRequestReadyForReviewEvent, PullRequestSynchronizeEvent } from "@octokit/webhooks-types";
import { ActionsCheckoutV4 } from "@github-actions-workflow-ts/actions";
import { startJob, TypedOutputsStep } from "./actions/base.ts";
import { githubEvent, githubEventRaw } from "./actions/github-context.ts";
import { ATOMA_WORKFLOW_PERMISSIONS } from "./actions/permissions.ts";
import { scriptCommand } from "./actions/script-call.ts";
import { SetupBunAction } from "./actions/third-party.ts";
import { dispatchToAtomaRunner } from "./atoma-runner.wac.ts";
import { ref as extractNotifyTagRef } from "../scripts/extract_notify_tag.ts";
import { ref as matchTriggerRef, type MatchTriggerEnv } from "../scripts/match_trigger.ts";

// Matches this workflow's own `on.pull_request_target.types` below -- used to
// type-check every `githubEvent()`/`githubEventRaw()` call in this file
// against the actual payload shape for exactly these 3 actions.
type AutoTriggerEvent = PullRequestOpenedEvent | PullRequestSynchronizeEvent | PullRequestReadyForReviewEvent;

// Generic workflow triggered by GitHub events.
// Uses pull_request_target (NOT pull_request) because GITHUB_TOKEN-created PRs
// trigger the event but GitHub suppresses workflow runs for pull_request events.
// pull_request_target runs in the base repo context with full write permissions.
//
// pull_request_review is handled in a separate workflow (atoma-pr-review.wac.ts)
// because pull_request_target and pull_request_review cannot be combined.
//
// Job graph:
//   route --> run (atoma-runner.yml, reusable)

const contextStep = new TypedOutputsStep(
  {
    name: "Determine PR number from event context",
    id: "context",
    shell: "bash",
    // This workflow's `on:` is exclusively `pull_request_target` (see below)
    // -- unlike a generic issues-or-PR handler, `github.event.pull_request`
    // is therefore always present, so there is no `github.event.issue`
    // fallback branch to type (there never was a real `issue`-only case to
    // handle here; typing this against the real payload is what surfaced
    // that the old if/else's `else` branch was dead).
    run: `echo "number=${githubEvent<AutoTriggerEvent>((e) => e.pull_request.number)}" >> "$GITHUB_OUTPUT"
echo "type=pr" >> "$GITHUB_OUTPUT"
`,
  },
  ["number", "type"] as const,
);

const notifyStep = new TypedOutputsStep(
  {
    name: "Resolve notify login from PR body tag",
    id: "notify",
    shell: "bash",
    env: { PR_BODY: githubEvent<AutoTriggerEvent>((e) => e.pull_request.body) },
    run: `${scriptCommand(extractNotifyTagRef)}\n`,
  },
  ["notify"] as const,
);

const matchStep = new TypedOutputsStep(
  {
    name: "Match event to agent from config.json",
    id: "match",
    shell: "bash",
    env: {
      EVENT_TYPE: `\${{ github.event_name }}.\${{ ${githubEventRaw<AutoTriggerEvent>((e) => e.action)} }}`,
      // `.review` doesn't exist on any pull_request_target payload (it's
      // exclusive to pull_request_review events, handled by the separate
      // atoma-pr-review.wac.ts) -- this always resolves empty for this
      // workflow, which `MatchTriggerEnv`'s optional `REVIEW_STATE` allows
      // for. Left as a plain string since there is no real field of this
      // event type to type-check it against.
      REVIEW_STATE: "${{ github.event.review.state }}",
      IS_DRAFT: githubEvent<AutoTriggerEvent>((e) => e.pull_request.draft),
    } satisfies MatchTriggerEnv,
    run: `AGENT=$(${scriptCommand(matchTriggerRef)} 2>/dev/null || true)
if [ -n "\${AGENT}" ]; then
  echo "Matched agent: \${AGENT}"
  echo "agent=\${AGENT}" >> "$GITHUB_OUTPUT"
  echo "number=${contextStep.outputs.number}" >> "$GITHUB_OUTPUT"
  echo "type=${contextStep.outputs.type}" >> "$GITHUB_OUTPUT"
fi
`,
  },
  ["agent", "number", "type"] as const,
);

export const atomaAutoTrigger = new Workflow("atoma-auto-trigger", {
  name: "Atoma Auto Trigger",
  on: {
    pull_request_target: { types: ["opened", "synchronize", "ready_for_review"] },
  },
  permissions: ATOMA_WORKFLOW_PERMISSIONS,
}).addJobs(
  startJob(
    "route",
    {
      "runs-on": "ubuntu-latest",
      outputs: {
        agent: matchStep.outputs.agent,
        number: matchStep.outputs.number,
        type: matchStep.outputs.type,
        notify: notifyStep.outputs.notify,
      },
    },
    [
      new ActionsCheckoutV4({}),
      // Required by the "Match event to agent" step below, which runs
      // match_trigger.ts via `bun run` -- not preinstalled on GitHub-hosted
      // runners.
      new SetupBunAction({ name: "Setup Bun" }),
      contextStep,
      notifyStep,
      matchStep,
    ],
  )
    .then((routeJob) => dispatchToAtomaRunner(routeJob, "inherit"))
    .jobs(),
);

import { Workflow } from "@github-actions-workflow-ts/lib";
import type { IssueCommentCreatedEvent } from "@octokit/webhooks-types";
import { ActionsCheckoutV4 } from "@github-actions-workflow-ts/actions";
import { startJob, TypedOutputsStep } from "./actions/base.ts";
import { githubEvent, githubEventRaw } from "./actions/github-context.ts";
import { ATOMA_WORKFLOW_PERMISSIONS } from "./actions/permissions.ts";
import { scriptCommand, scriptCommandWithArgs } from "./actions/script-call.ts";
import { SetupBunAction } from "./actions/third-party.ts";
import { dispatchToAtomaRunner } from "./atoma-runner.wac.ts";
import { ref as parseCommentCommandRef } from "../scripts/parse_comment_command.ts";
import { ref as guardCommentRef } from "../scripts/guard_comment_during_run.ts";

// Invoke agents via /agent-name slash command in issue/PR comments.
// Slash-command DISPATCH is restricted to OWNER/MEMBER/COLLABORATOR (see
// parseCommandStep's own `if:` below), but the in-progress GUARD (see
// guardStep) runs for every human comment regardless of association --
// nobody's comment should sit unseen (or race a dispatch) while an Atoma
// run is actively working on this issue/PR.
//
// Job graph:
//   parse --> run (atoma-runner.yml, reusable)

// Bot comments are never guarded (Atoma's own comments, e.g. dispatch
// confirmations, must never be self-deleted) -- only ever relevant for a
// human-authored comment.
const IS_HUMAN_COMMENT = `${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.user.type)} != 'Bot'`;

const guardStep = new TypedOutputsStep(
  {
    name: "Guard: reject comment while atoma/in-progress",
    id: "guard",
    if: IS_HUMAN_COMMENT,
    shell: "bash",
    env: {
      GH_TOKEN: "${{ github.token }}",
      NUMBER: githubEvent<IssueCommentCreatedEvent>((e) => e.issue.number),
      COMMENT_ID: githubEvent<IssueCommentCreatedEvent>((e) => e.comment.id),
      COMMENTER: githubEvent<IssueCommentCreatedEvent>((e) => e.comment.user.login),
    },
    run: `${scriptCommandWithArgs(guardCommentRef, { number: "\${NUMBER}", "comment-id": "\${COMMENT_ID}", commenter: "\${COMMENTER}" })}\n`,
  },
  ["blocked"] as const,
);

// Original OWNER/MEMBER/COLLABORATOR-or-bot-dispatch-tag restriction on
// actually DISPATCHING a slash command (unchanged from before) -- the job
// itself now also runs for non-qualifying humans (see the job's own `if:`
// below), but only to let guardStep do its job; this step still refuses to
// parse/dispatch for them.
const PARSE_ALLOWED =
  `(${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.user.type)} == 'Bot' &&\n` +
  ` contains(${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.body)}, 'atoma:dispatch')) ||\n` +
  `(${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.user.type)} != 'Bot' &&\n` +
  ` (${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.author_association)} == 'OWNER' ||\n` +
  `  ${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.author_association)} == 'MEMBER' ||\n` +
  `  ${githubEventRaw<IssueCommentCreatedEvent>((e) => e.comment.author_association)} == 'COLLABORATOR'))`;

const parseCommandStep = new TypedOutputsStep(
  {
    name: "Parse slash command",
    id: "command",
    if: `(${PARSE_ALLOWED}) && steps.guard.outputs.blocked != 'true'`,
    shell: "bash",
    env: {
      ATOMA_COMMENT_BODY: githubEvent<IssueCommentCreatedEvent>((e) => e.comment.body),
    },
    run: `${scriptCommand(parseCommentCommandRef)}\n`,
  },
  ["matched", "agent", "session_mode", "error"] as const,
);

const targetStep = new TypedOutputsStep(
  {
    name: "Resolve target context",
    id: "target",
    shell: "bash",
    env: {
      NUMBER: githubEvent<IssueCommentCreatedEvent>((e) => e.issue.number),
      IS_PR: `\${{ toJSON(${githubEventRaw<IssueCommentCreatedEvent>((e) => e.issue.pull_request)} != null) }}`,
      NOTIFY: githubEvent<IssueCommentCreatedEvent>((e) => e.comment.user.login),
    },
    run: `echo "number=\${NUMBER}" >> "$GITHUB_OUTPUT"
if [ "$IS_PR" = "true" ]; then
  echo "type=pr" >> "$GITHUB_OUTPUT"
else
  echo "type=issue" >> "$GITHUB_OUTPUT"
fi
echo "notify=\${NOTIFY}" >> "$GITHUB_OUTPUT"
`,
  },
  ["number", "type", "notify"] as const,
);

const commandErrorStep = new TypedOutputsStep({
  name: "Report invalid slash command",
  if: `${parseCommandStep.rawOutputs.error} != ''`,
  shell: "bash",
  env: {
    GH_TOKEN: "${{ github.token }}",
    NUMBER: targetStep.outputs.number,
    ERROR: parseCommandStep.outputs.error,
  },
