/**
 * tags.ts — canonical encode/decode for every `<!-- atoma:xxx=... -->`
 * HTML-comment marker Atoma embeds in issue/PR bodies and comments to carry
 * state across otherwise-stateless GitHub Actions workflow runs.
 *
 * This is the ONE place each tag's
 * wire format is defined; every reader/writer imports from here instead of
 * re-deriving its own regex.
 */

export interface AtomaTag<T> {
  /** Render this tag's HTML-comment form, ready to prepend/embed in a body or comment. */
  write(value: T): string;
  /** Extract this tag's value from anywhere in `text`, or undefined if absent. */
  read(text: string): T | undefined;
  /** True if `text` contains this tag at all, regardless of its value. */
  has(text: string): boolean;
}

function makeTag<T>(key: string, valuePattern: string, parse: (raw: string) => T, render: (value: T) => string): AtomaTag<T> {
  const re = new RegExp(`<!--\\s*atoma:${key}=(${valuePattern})\\s*-->`);
  return {
    write: (value) => `<!-- atoma:${key}=${render(value)} -->`,
    read: (text) => {
      const m = re.exec(text);
      return m ? parse(m[1]!) : undefined;
    },
    has: (text) => re.test(text),
  };
}

/** Numeric-valued tag, e.g. `atoma:foo=42`. */
function numericTag(key: string): AtomaTag<number> {
  return makeTag(key, "\\d+", Number, String);
}

/** String-valued tag, e.g. `atoma:foo=bar-baz`. */
function stringTag(key: string, valuePattern: string): AtomaTag<string> {
  return makeTag(key, valuePattern, (raw) => raw, (value) => value);
}

/** Sub-issue -> orchestrator parent ISSUE link (set via `github__create_issue`'s `sub_issue: true`). */
export const PARENT_TAG = numericTag("parent");
/** PR -> the issue it closes/was created to address (set via `github__create_pr`). */
export const PARENT_ISSUE_TAG = numericTag("parent-issue");
/** Who to `@mention` on completion/escalation. */
export const NOTIFY_TAG = stringTag("notify", "[A-Za-z0-9-]+");
/** Which agent originally created a PR (for post-merge/rejection re-invocation). */
export const ORIGIN_AGENT_TAG = stringTag("origin-agent", "[a-z][a-z0-9-]*");
/** Slash-command-equivalent dispatch marker on a bot-authored comment. */
export const DISPATCH_TAG = stringTag("dispatch", "[a-z][a-z0-9-]*");
/** Tags a posted result comment with which agent generated it (used by reconcile_github_session.ts to exclude an agent's own past comments from its future shared context). */
export const AGENT_TAG = stringTag("agent", "[a-z][a-z0-9-]*");
/** Marks a GitHub comment as human-visible operational audit only; excluded from future LLM context reconciliation. */
export const LLM_CONTEXT_TAG = stringTag("llm-context", "include|exclude");
/** Idempotency marker: orchestrator dispatch was already triggered for a given closed sub-issue's completion (see lib/aggregation.ts). Fresh tag with no pre-existing data, written as plain `N`. */
export const AGGREGATED_TAG = numericTag("aggregated");
/** Progress marker: which sub-issue's completion a progress comment reports on. Write-only (nothing parses it back); written as plain `N`. */
export const SUB_RESULT_TAG = numericTag("sub-result");

/**
 * Resolve a `parent` link from EITHER `atoma:parent` (issue -> issue) or
 * `atoma:parent-issue` (PR -> issue), preferring whichever is present --
 * mirrors the original combined regex used by resolve_notify.ts's
 * parent-chain walk, where a body may carry either form depending on
 * whether it's an issue or a PR.
 */
export function readAnyParentTag(text: string): number | undefined {
  return PARENT_TAG.read(text) ?? PARENT_ISSUE_TAG.read(text);
}

#!/usr/bin/env bun
/**
 * save_agent_session.ts — Save session.json to the atoma-data branch (via
 * lib/atoma-data.ts's saveSession(), which handles push-race retries using
 * an isolated git worktree).
 *
 * Usage: save_agent_session.ts --session session.json --type issue|pr --number N --agent NAME
 * No-ops quietly if --session doesn't exist.
 */
import { existsSync, readFileSync } from "node:fs";
import { parseArgs } from "node:util";
import { saveSession, sessionTargetPath } from "./lib/atoma-data.ts";
import { defineScript } from "./lib/script-ref.ts";

export interface SaveAgentSessionArgs {
  session: string;
  type: string;
  number: string | number;
  agent: string;
}

export const ref = defineScript<SaveAgentSessionArgs>(import.meta.url);

function main(): void {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      session: { type: "string" },
      type: { type: "string" },
      number: { type: "string" },
      agent: { type: "string" },
    },
  });
  if (!values.session || !values.type || !values.number || !values.agent) {
    console.error("usage: save_agent_session.ts --session FILE --type issue|pr --number N --agent NAME");
    process.exit(2);
  }
  if (!existsSync(values.session)) {
    console.error("No session.json found, skipping save.");
    return;
  }

  const target = sessionTargetPath(values.type, values.number, values.agent);
  const content = readFileSync(values.session, "utf8");
  const runId = process.env.GITHUB_RUN_ID ?? "";
  const saved = saveSession(target, content, `session: ${values.agent} on ${values.type} ${values.number} (run ${runId})`);
  if (!saved) {
    console.log(`::warning::Failed to save session to atoma-data:${target} after all retries.`);
  } else {
    console.error(`Session saved to atoma-data:${target}`);
  }
}

if (import.meta.main) main();

/**
 * atoma-data.ts — helpers for reading/writing per-agent session.json files
 * on the orphan `atoma-data` git branch, this repo's persistent session
 * store (GitHub Actions runners have no other durable storage between runs).
 */
import { existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { gitRun } from "../../lib/gh.ts";

/** Path of a given agent's session file on the atoma-data branch. */
export function sessionTargetPath(type: string, number: string | number, agent: string): string {
  return `sessions/${type}-${number}/${agent}.json`;
}

export function nextArchiveSessionPath(
  type: string,
  number: string | number,
  agent: string,
  existingNames: readonly string[],
): string {
  const escapedAgent = agent.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const archivePattern = new RegExp(`^${escapedAgent}-(\\d+)\\.json$`);
  const nextNumber = existingNames
    .map((name) => archivePattern.exec(name))
    .filter((match): match is RegExpExecArray => match !== null)
    .reduce((max, match) => Math.max(max, Number(match[1])), 0) + 1;
  return `sessions/${type}-${number}/archive/${agent}-${nextNumber}.json`;
}

/**
 * Reads `targetPath`'s content from the `atoma-data` branch's tip on
 * `origin`, WITHOUT checking out or otherwise disturbing the current
 * working tree/branch (just `git fetch` + `git show <ref>:<path>`).
 * Returns undefined if the branch, or the file within it, doesn't exist yet.
 */
export function restoreSession(targetPath: string): string | undefined {
  if (gitRun("fetch", "origin", "atoma-data", "--depth=1").code !== 0) {
    return undefined;
  }
  if (gitRun("cat-file", "-e", `origin/atoma-data:${targetPath}`).code !== 0) {
    return undefined;
  }
  const shown = gitRun("show", `origin/atoma-data:${targetPath}`);
  return shown.code === 0 ? shown.stdout : undefined;
}

function gitIn(cwd: string, ...args: string[]): { code: number; stdout: string } {
  const proc = Bun.spawnSync({ cmd: ["git", ...args], cwd, stdout: "pipe", stderr: "pipe" });
  return { code: proc.exitCode ?? 1, stdout: proc.stdout ? proc.stdout.toString("utf8").trim() : "" };
}

/**
 * Writes `content` to `targetPath` on the `atoma-data` branch and pushes it,
 * retrying on push races (parallel agents -- e.g. sibling sub-issue
 * engineers running at the same time -- each write to their own uniquely
 * named target path, but all push to the SAME atoma-data branch, so a race
 * is expected, not exceptional).
 *
 * Uses a separate git worktree (unlike `restoreSession`, which is a safe
 * read-only `git show`) so the CURRENT checkout/branch -- which may hold the
 * agent's own real, possibly-uncommitted code changes at this point in the
 * job -- is never disturbed. Returns true if the save succeeded (or the
 * content was already identical -- a no-op "save").
 */
export function saveSession(targetPath: string, content: string, commitMessage: string): boolean {
  if (gitRun("ls-remote", "--exit-code", "origin", "atoma-data").code !== 0) {
    gitRun("config", "user.email", "action@github.com");
    gitRun("config", "user.name", "GitHub Actions");
    // 4b825dc6... is Git's canonical empty-tree SHA (never changes).
    const commit = gitRun("commit-tree", "4b825dc642cb6eb9a060e54bf8d69288fbee4904", "-m", "init: atoma-data session store").stdout;
    gitRun("push", "origin", `${commit}:refs/heads/atoma-data`);
  }

  gitRun("fetch", "origin", "atoma-data");
  const worktreeDir = mkdtempSync(join(tmpdir(), "atoma-data-wt-"));
  gitRun("worktree", "add", worktreeDir, "origin/atoma-data");

  let saved = false;
  try {
    gitIn(worktreeDir, "config", "user.email", "action@github.com");
    gitIn(worktreeDir, "config", "user.name", "GitHub Actions");

    for (let attempt = 1; attempt <= 5; attempt++) {
      gitIn(worktreeDir, "fetch", "origin", "atoma-data");
      gitIn(worktreeDir, "reset", "--hard", "origin/atoma-data");

      const fullTarget = join(worktreeDir, targetPath);
      mkdirSync(dirname(fullTarget), { recursive: true });
      writeFileSync(fullTarget, content);
      gitIn(worktreeDir, "add", targetPath);

      if (gitIn(worktreeDir, "diff", "--cached", "--quiet").code === 0) {
        saved = true;
        break;
      }

      gitIn(worktreeDir, "commit", "-m", commitMessage);

      if (gitIn(worktreeDir, "push", "origin", "HEAD:atoma-data").code === 0) {
        saved = true;
        break;
      }

      console.error(`Push attempt ${attempt} failed (concurrent push) -- resetting and retrying with a fresh pull...`);
      Bun.sleepSync(attempt * 2000);
    }
  } finally {
    gitRun("worktree", "remove", "--force", worktreeDir);
    rmSync(worktreeDir, { recursive: true, force: true });
  }

  return saved;
}

/**
 * Preserve a session before recovery as the next numbered archive entry.
 * Number allocation happens inside the retrying atoma-data worktree so two
 * recoveries racing on the same context cannot select the same archive path.
 */
export function archiveSession(
  type: string,
  number: string | number,
  agent: string,
  content: string,
): string | undefined {
  if (gitRun("ls-remote", "--exit-code", "origin", "atoma-data").code !== 0) return undefined;

  gitRun("fetch", "origin", "atoma-data");
  const worktreeDir = mkdtempSync(join(tmpdir(), "atoma-data-archive-wt-"));
  gitRun("worktree", "add", worktreeDir, "origin/atoma-data");

  let archivedPath: string | undefined;
  try {
    gitIn(worktreeDir, "config", "user.email", "action@github.com");
    gitIn(worktreeDir, "config", "user.name", "GitHub Actions");

    for (let attempt = 1; attempt <= 5; attempt++) {
      gitIn(worktreeDir, "fetch", "origin", "atoma-data");
      gitIn(worktreeDir, "reset", "--hard", "origin/atoma-data");

      const archiveDir = join(worktreeDir, `sessions/${type}-${number}/archive`);
      mkdirSync(archiveDir, { recursive: true });
      const relativePath = nextArchiveSessionPath(type, number, agent, readdirSync(archiveDir));
      const fullPath = join(worktreeDir, relativePath);
      if (existsSync(fullPath)) continue;

      writeFileSync(fullPath, content);
      gitIn(worktreeDir, "add", relativePath);
      gitIn(worktreeDir, "commit", "-m", `session: archive ${agent} on ${type} ${number}`);

      if (gitIn(worktreeDir, "push", "origin", "HEAD:atoma-data").code === 0) {
        archivedPath = relativePath;
        break;
      }

      console.error(`Archive push attempt ${attempt} failed -- retrying with the latest atoma-data branch.`);
      Bun.sleepSync(attempt * 2000);
    }
  } finally {
    gitRun("worktree", "remove", "--force", worktreeDir);
    rmSync(worktreeDir, { recursive: true, force: true });
  }

  return archivedPath;
}
